# Load the prepared data (see tools/ for how each file was made) into plain R objects.

DAYS <- c("mon", "tue", "wed", "thu", "fri", "sat", "sun")
CATEGORY_ORDER <- c("Landmarks", "Museums & galleries", "Parks & gardens", "Laneways & shopping",
                    "Markets & food", "Views & attractions")
DAY_LABELS <- c("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")

hhmm_to_min <- function(x) {
  p <- strsplit(x, ":", fixed = TRUE)
  vapply(p, function(v) as.numeric(v[1]) * 60 + as.numeric(v[2]), numeric(1))
}
fmt_time <- function(m) {
  m <- round(m)
  sprintf("%02d:%02d", (m %/% 60) %% 24, m %% 60)
}
fmt_dur <- function(m) {      # in the current language (tr(), R/i18n.R)
  m <- round(m)
  if (m < 60) return(sprintf(tr("%d min"), m))
  if (m %% 60 == 0) sprintf(tr("%d h"), m %/% 60) else sprintf(tr("%d h %d min"), m %/% 60, m %% 60)
}

# "09:00-17:00" -> c(540, 1020); "closed" / "" -> c(NA, NA)
parse_hours <- function(x) {
  if (is.na(x) || x == "" || tolower(x) == "closed") return(c(NA_real_, NA_real_))
  hhmm_to_min(strsplit(x, "-", fixed = TRUE)[[1]])
}

load_app_data <- function(dir = "data") {
  places <- read.csv(file.path(dir, "places.csv"), stringsAsFactors = FALSE, na.strings = "")
  starts <- read.csv(file.path(dir, "start_points.csv"), stringsAsFactors = FALSE)

  # Walking minutes (W) and metres (M) between every pair of nodes (places first, then preset start points).
  nodes <- c(places$id, setdiff(starts$id, places$id))
  wm <- read.csv(file.path(dir, "walk_matrix.csv"), stringsAsFactors = FALSE)
  W <- M <- matrix(0, length(nodes), length(nodes), dimnames = list(nodes, nodes))
  W[cbind(wm$from, wm$to)] <- wm$minutes
  M[cbind(wm$from, wm$to)] <- wm$metres

  # Street-following line for each pair, stored once per pair.
  gj <- jsonlite::fromJSON(file.path(dir, "walk_legs.geojson"), simplifyVector = FALSE)
  legs <- list()
  for (f in gj$features) {
    xy <- do.call(rbind, lapply(f$geometry$coordinates, unlist))
    legs[[paste(f$properties$from, f$properties$to, sep = "|")]] <- xy
  }

  # Opening hours per place x weekday.
  open <- close <- matrix(NA_real_, nrow(places), 7)
  for (d in 1:7) {
    h <- t(vapply(places[[DAYS[d]]], parse_hours, numeric(2)))
    open[, d] <- h[, 1]; close[, d] <- h[, 2]
  }
  last_entry <- ifelse(is.na(places$last_entry), NA_real_,
                       suppressWarnings(hhmm_to_min(ifelse(is.na(places$last_entry), "0:0", places$last_entry))))

  # Average pedestrians per hour at each place's nearest sensor: places x weekday x hour.
  ped <- read.csv(file.path(dir, "pedestrian_sensor_weekday_hour.csv"))
  busy <- array(NA_real_, c(nrow(places), 7, 24))
  for (i in which(!is.na(places$sensor_id))) {
    p <- ped[ped$sensor_id == places$sensor_id[i], ]
    busy[cbind(i, p$weekday, p$hour + 1)] <- p$mean_count
  }
  # Quiet / moderate / busy: the same fixed cut points everywhere (BUSY_BREAKS below).
  cuts <- BUSY_BREAKS

  read_points <- function(f) {
    g <- jsonlite::fromJSON(file.path(dir, f), simplifyVector = FALSE)$features
    xy <- t(vapply(g, function(x) as.numeric(unlist(x$geometry$coordinates))[1:2], numeric(2)))
    props <- lapply(g, function(x) x$properties)
    list(lon = xy[, 1], lat = xy[, 2], props = props)
  }

  list(places = places, starts = starts, nodes = nodes, W = W, M = M, legs = legs,
       open = open, close = close, last_entry = last_entry, busy = busy, busy_cuts = cuts,
       toilets = read_points("toilets.geojson"), fountains = read_points("drinking_fountains.geojson"))
}

# Street busyness levels, used by the map, the plan, the home page's time strip, the quiet-hours view
# and the Tableau workbook alike, so a colour always means the same number of people: under 300
# people per hour is quiet, 300 to 900 moderate, 900 or more busy. Round numbers a visitor can read off
# the legend; at our places' sensors (8-22 h) they split the hours about 30 / 45 / 25 %.
BUSY_BREAKS <- c(300, 900)
BUSY_RANGES <- c("<300", "300–900", "900+")
busy_level <- function(count, cuts = BUSY_BREAKS) {
  ifelse(is.na(count), NA_integer_, ifelse(count < cuts[1], 1L, ifelse(count < cuts[2], 2L, 3L)))
}
BUSY_LABELS <- c("Quiet street", "Moderate", "Busy street")

leg_coords <- function(D, a, b) {
  xy <- D$legs[[paste(a, b, sep = "|")]]
  if (!is.null(xy)) return(xy)
  xy <- D$legs[[paste(b, a, sep = "|")]]
  if (!is.null(xy)) return(xy[nrow(xy):1, , drop = FALSE])
  NULL
}

hav_m <- function(lon1, lat1, lon2, lat2) {
  r <- pi / 180
  h <- sin((lat2 - lat1) * r / 2)^2 + cos(lat1 * r) * cos(lat2 * r) * sin((lon2 - lon1) * r / 2)^2
  2 * 6371008 * asin(sqrt(h))
}

# Distance (m) from a place to its nearest toilet / drinking fountain.
nearest_amenity <- function(pts, lon, lat) {
  d <- hav_m(lon, lat, pts$lon, pts$lat)
  k <- which.min(d)
  list(m = d[k], i = k)
}

# Home page plan: which places go into which part of which free time.
#
# A slot is one part (morning 8-12, afternoon 12-17, evening 17-22) of one free time, keyed
# "<window id>|<part>" (window_parts(), R/bundles.R); "<window id>|any" holds places added on a day
# page, which may go anywhere in that free time. `slots` is a named list: key -> place ids. The visitor
# fills slots by dragging a place or a ready-made walk into them, or presses + and we pick a slot. Only
# the places are decided here; the order, the times and the route are worked out on the day page
# (R/planner.R), where a slot's places are visited after the earlier parts' ones and not before their
# part starts.
#
# Whether something fits a slot (fit_check): every place is open long enough inside the slot, and the
# stays plus the walks between them (nearest-neighbour order, bundle_walk) leave the slack free ("ok")
# or at least fit in the slot ("tight"); otherwise "no". A free time takes at most MAX_STOPS places,
# because the day page tries every order. A place is planned once only.

SLOT_ANY <- "any"
`%||%` <- function(a, b) if (is.null(a)) b else a

slot_key <- function(wid, part) paste(wid, part, sep = "|")
slot_window <- function(key) sub("\\|.*", "", key)
slot_part <- function(key) sub(".*\\|", "", key)

# Place ids planned in free time `wid`: its parts in time order, then the ones added on the day page.
window_places <- function(slots, wid) {
  keys <- intersect(slot_key(wid, c(PARTS$part, SLOT_ANY)), names(slots))
  unique(unlist(slots[keys], use.names = FALSE))
}
planned_ids <- function(slots) unique(unlist(slots, use.names = FALSE))
where_planned <- function(slots, id) {
  k <- names(slots)[vapply(slots, function(x) id %in% x, logical(1))]
  if (length(k)) k[1] else NA_character_
}

# stops: place indices; part: a row of window_parts() (t0, t1, day).
fit_check <- function(D, stops, part, pace = "normal") {
  if (length(stops) == 0) return(list(status = "ok", minutes = 0, why = ""))
  stay <- D$places$stay_min[stops] * PACES[[pace]]$stay
  o <- D$open[stops, part$day]; cl <- D$close[stops, part$day]
  bad <- which(is.na(o) | pmin(cl, part$t1) - pmax(o, part$t0) < stay)
  if (length(bad)) {
    i <- stops[bad[1]]
    why <- if (is.na(o[bad[1]])) sprintf(tr("%s is closed on %s."), place_name(D, i), day_name(part$day, "plural"))
           else sprintf(tr("%s is open %s on %s, not long enough in this part of the day."), place_name(D, i),
                        hours_text(o[bad[1]], cl[bad[1]]), day_name(part$day, "plural"))
    return(list(status = "no", minutes = NA_real_, why = why))
  }
  m <- bundle_walk(D, stops, pace)$minutes
  len <- part$t1 - part$t0
  if (m <= len - slack_for(len)) list(status = "ok", minutes = m, why = "")
  else if (m <= len) list(status = "tight", minutes = m, why = "")
  else list(status = "no", minutes = m,
            why = sprintf(tr("That would be %s of visits and walking in a %s part of the day."), fmt_dur(m), fmt_dur(len)))
}

# What happens if `item` goes into slot `key`: "place:<id>" joins what is there, "walk:<id>" replaces it.
drop_check <- function(D, B, parts, slots, key, item, pace = "normal") {
  part <- parts[parts$key == key, ]
  kind <- sub(":.*", "", item); id <- sub("^[a-z]+:", "", item)
  wid <- slot_window(key)
  if (kind == "place") {
    stops <- union(slots[[key]], id)
    others <- setdiff(window_places(slots[setdiff(names(slots), key)], wid), id)
  } else {
    k <- match(id, B$id)
    stops <- D$places$id[B$core[[k]]]
    part <- bundle_part(B, k, part)
    others <- setdiff(window_places(slots[setdiff(names(slots), key)], wid), stops)
  }
  if (length(stops) + length(others) > MAX_STOPS)
    return(list(status = "no", why = sprintf(tr("A free time takes up to %d places; this one would have %d."),
                                             MAX_STOPS, length(stops) + length(others))))
  fit_check(D, match(stops, D$places$id), part, pace)
}

# Status of every place and walk in every slot, for colouring the slots while something is dragged:
# list(place = list(id = c(key = status)), walk = list(id = c(key = status))).
fit_table <- function(D, B, parts, slots, pace = "normal") {
  one <- function(item, here = NA_character_) vapply(parts$key, function(key)
    if (!is.na(here) && key == here) "here" else drop_check(D, B, parts, slots, key, item, pace)$status, character(1))
  list(place = setNames(lapply(D$places$id, function(id) one(paste0("place:", id), where_planned(slots, id))), D$places$id),
       walk = setNames(lapply(B$id, function(id) one(paste0("walk:", id))), B$id))
}

# Put `item` into slot `key`. A place moves there from wherever it was; a walk replaces what is in the
# slot, and its places leave the other slots. `walks` records which walk a slot came from.
slot_put <- function(D, B, slots, walks, key, item) {
  kind <- sub(":.*", "", item); id <- sub("^[a-z]+:", "", item)
  ids <- if (kind == "place") id else D$places$id[B$core[[match(id, B$id)]]]
  slots <- lapply(slots, function(x) setdiff(x, ids))
  if (kind == "place") slots[[key]] <- union(slots[[key]], id)
  else { slots[[key]] <- ids; walks[[key]] <- id }
  slots <- slots[lengths(slots) > 0]
  walks <- walks[names(walks) %in% names(slots)]
  list(slots = slots, walks = walks)
}

slot_remove <- function(slots, walks, id) {
  slots <- lapply(slots, function(x) setdiff(x, id))
  slots <- slots[lengths(slots) > 0]
  list(slots = slots, walks = walks[names(walks) %in% names(slots)])
}

# The slot + would choose for `item`, or NA. A place goes where it adds the least walking among the
# slots it fits with slack to spare (else where it fits at all): next to places already planned
# nearby, or, in an empty slot, close to where that free time starts. A walk goes into the first
# empty slot it fits, preferring its suggested part of the day.
auto_slot <- function(D, B, ws, parts, slots, item, pace = "normal") {
  if (nrow(parts) == 0) return(NA_character_)
  kind <- sub(":.*", "", item); id <- sub("^[a-z]+:", "", item)
  st <- vapply(parts$key, function(key) drop_check(D, B, parts, slots, key, item, pace)$status, character(1))
  if (kind == "walk") {
    k <- match(id, B$id)
    ok <- which(st == "ok" & lengths(slots[parts$key]) == 0)
    if (length(ok) == 0) return(NA_character_)
    return(parts$key[ok[order(parts$part[ok] != B$best_slot[k])][1]])
  }
  for (want in c("ok", "tight")) {
    ok <- which(st == want)
    if (length(ok) == 0) next
    i <- match(id, D$places$id)
    extra <- vapply(ok, function(r) {
      cur <- match(slots[[parts$key[r]]], D$places$id)
      if (length(cur)) {
        bundle_walk(D, c(cur, i), pace)$minutes - bundle_walk(D, cur, pace)$minutes
      } else {
        w <- ws[ws$id == parts$window[r], ]
        D$places$stay_min[i] * PACES[[pace]]$stay + D$W[match(w$start, D$nodes), i] * PACES[[pace]]$walk
      }
    }, numeric(1))
    return(parts$key[ok[order(extra)][1]])
  }
  NA_character_
}

# A ready-made walk suggested for every empty slot, in time order: the best one that fits with slack
# and shares no place with what is planned or suggested already (rows of B, by slot key).
slot_suggestions <- function(D, B, parts, slots, walks, pace = "normal") {
  used <- match(planned_ids(slots), D$places$id)
  taken <- unlist(walks, use.names = FALSE)
  extra <- list()                              # suggested places per free time
  out <- list()
  for (r in seq_len(nrow(parts))) {
    key <- parts$key[r]
    if (length(slots[[key]])) next
    wid <- parts$window[r]
    room <- MAX_STOPS - length(window_places(slots, wid)) - length(extra[[wid]])
    s <- suggest_bundles(D, B, parts[r, ], NULL, c(taken, B$id[unlist(out)]), pace, room, used)
    if (length(s)) {
      out[[key]] <- s[1]
      used <- c(used, B$core[[s[1]]])
      extra[[wid]] <- c(extra[[wid]], B$core[[s[1]]])
    }
  }
  out
}

# For the day page of free time `wid`: per place, the earliest time it may be visited (its part's
# start, or its walk's start time), and its part's number for keeping the parts in order (NA for
# places added on the day page, which may go anywhere).
slot_not_before <- function(D, B, parts, slots, walks, wid) {
  nb <- rep(NA_real_, nrow(D$places))
  for (key in intersect(parts$key[parts$window == wid], names(slots))) {
    p <- parts[parts$key == key, ]
    if (!is.null(walks[[key]])) p <- bundle_part(B, match(walks[[key]], B$id), p)
    nb[match(slots[[key]], D$places$id)] <- p$t0
  }
  nb
}
slot_groups <- function(slots, wid, s) {
  g <- vapply(s, function(id) {
    k <- where_planned(slots, id)
    if (is.na(k) || slot_window(k) != wid) NA_integer_ else match(slot_part(k), PARTS$part)
  }, integer(1))
  if (all(is.na(g))) NULL else unname(g)
}

# The home page shows each part with the same plan the day page opens on (`opt`, the shortest-walk plan
# of free time `wid`, with its context `cx`), so the two pages never disagree. The parts split the free
# time by the clock (the first from the start of the free time, the last to its end, so their lengths
# add up to the whole), and every minute of walking or visiting counts for the part it happens in;
# waiting for a place to open is free time, as on the day page. Running past the end of the free time
# counts against the last part. `tight`: the day page's own test (less than the slack of the whole
# free time left unplanned); a part is shown as tight only then, and since all parts with room to
# spare add up to a free time with room to spare, a tight day always has a tight part. `bad`: a stop
# whose visit starts in that part is closed or closes too early.
part_minutes <- function(parts, wid, opt, cx) {
  P <- parts[parts$window == wid, ]
  P <- P[order(P$t0), ]
  n <- nrow(P)
  out <- list(minutes = setNames(numeric(n), P$key), len = setNames(numeric(n), P$key),
              bad = setNames(logical(n), P$key), tight = FALSE)
  if (n == 0) return(out)
  lo <- c(cx$t0, P$t0[-1]); hi <- c(P$t0[-1], cx$deadline)
  out$len[] <- hi - lo
  if (is.null(opt)) return(out)
  k <- length(opt$order)
  a <- c(opt$arrive - opt$walk_in, opt$start, opt$end[k])     # walks in, visits, walk back
  b <- c(opt$arrive, opt$end, opt$finish)
  hi[n] <- Inf
  for (j in seq_len(n)) out$minutes[j] <- sum(pmax(0, pmin(b, hi[j]) - pmax(a, lo[j])))
  for (s in which(opt$problem > 0)) out$bad[max(1, findInterval(opt$start[s], lo))] <- TRUE
  len <- cx$deadline - cx$t0
  out$tight <- len - sum(out$minutes) < slack_for(len)
  out
}

# Keep the slots in step with changed free times: places in a part that no longer has free time move to
# "any" of their free time; free times that are gone take their places with them.
prune_slots <- function(ws, parts, slots, walks) {
  out <- list()
  for (key in names(slots)) {
    wid <- slot_window(key)
    if (!(wid %in% ws$id)) next
    to <- if (key %in% parts$key || slot_part(key) == SLOT_ANY) key else slot_key(wid, SLOT_ANY)
    out[[to]] <- union(out[[to]], slots[[key]])
  }
  list(slots = out, walks = walks[names(walks) %in% intersect(names(out), parts$key)])
}

# Places to slots one at a time, as + would (used for the examples and when the free times are replaced).
auto_fill <- function(D, B, ws, ids, pace = "normal") {
  parts <- window_parts(ws)
  slots <- list(); walks <- list(); left <- character()
  for (id in ids) {
    key <- auto_slot(D, B, ws, parts, slots, paste0("place:", id), pace)
    if (is.na(key)) { left <- c(left, id); next }
    r <- slot_put(D, B, slots, walks, key, paste0("place:", id))
    slots <- r$slots; walks <- r$walks
  }
  list(slots = slots, walks = walks, left = left)
}

