# You need to install the shinyjs package before you can use this!
library(shinyjs)

# Call this function from navbarPage(header=...) or anywhere else suitable
# in the Shiny UI
setUpTableauInShiny <- function() {
  registerInputHandler("tinsdf", function(x, session, inputname) {
    jsonlite::fromJSON(x)
  }, force=TRUE)
  
  list(
    useShinyjs(),
    HTML('<script type="module">
      // Import all Tableau objects into the global namespace
      import * as T from "https://public.tableau.com/javascripts/api/tableau.embedding.3.latest.js";
      Object.assign(window, T);
      
      // Map a few common Tableau JS events to Shiny R events
      window.observeTableauEvents = id => {
        const viz = document.getElementById(id);
        viz.addEventListener(TableauEventType.MarkSelectionChanged, async e => {
          const marks = await e.detail.getMarksAsync();
          const columnNames = marks.data[0].columns.map(col => col.fieldName);
          const dataTable = marks.data[0].data.map(row => row.map(val => val.value));
          const dataForShiny = dataTable.map(row => 
            Object.fromEntries(columnNames.map((_, i) => [columnNames[i], row[i]])));
          Shiny.setInputValue(id + "_mark_selection_changed:tinsdf", JSON.stringify(dataForShiny));
        });
        viz.addEventListener(TableauEventType.FilterChanged, async e => {
          const filter = await e.detail.getFilterAsync();
          Shiny.setInputValue(id + "_filter_changed", {
            fieldName: e.detail.fieldName,
            isAllSelected: filter.isAllSelected,
            appliedValues: filter.appliedValues.map(app => app.value)
          });
        });
        viz.addEventListener(TableauEventType.ParameterChanged, async e => {
          const param = await e.detail.getParameterAsync();
          Shiny.setInputValue(id + "_parameter_changed", {
            name: param.name,
            fieldName: param.id,
            value: param.currentValue.value
          });
        });
        console.log("added events for", id)
      };
    </script>')
  )
}

# For inserting a viz into the Shiny UI
tableauPublicViz <- function(id, url, height="500px", style=NA, ...) {
  list(
    tag('tableau-viz', list(id=id,
                            src=url,
                            style=paste0('height: ', height, ';', if (is.na(style)) '' else style),
                            ...)),
    HTML(sprintf('<script>document.addEventListener("DOMContentLoaded", () => {
      observeTableauEvents("%s");
    }, false);</script>', id))
  )
}

// Tableau events (mark selection, filters, parameters) are wired up by the Week 8 library
// tableau-in-shiny-v1.2.R. This only tells the server when a viz has finished loading, so the
// current place filter can be applied to it (input$<id>_ready).
document.addEventListener("firstinteractive", function (e) {
  if (e.target && e.target.id && window.Shiny && Shiny.setInputValue)
    Shiny.setInputValue(e.target.id + "_ready", Date.now());
}, true);

// Hovering a stop in the timeline or the plan list highlights it on the map.
document.addEventListener("mouseover", function (e) {
  var el = e.target.closest && e.target.closest("[data-place]");
  if (!el || !window.Shiny || !Shiny.setInputValue) return;
  if (el.dataset.place === window.__lastHover) return;
  window.__lastHover = el.dataset.place;
  Shiny.setInputValue("hover_place", el.dataset.place, { priority: "event" });
});

// Top bar: the free-time tabs scroll sideways. Arrows show only when some tabs are out of view;
// the mouse wheel also scrolls the strip, and the open free time is kept in view.
function updateTabArrows() {
  var t = document.getElementById("date_tabs");
  if (!t) return;
  var strip = t.parentElement;
  strip.classList.toggle("can-left", t.scrollLeft > 2);
  strip.classList.toggle("can-right", t.scrollLeft + t.clientWidth < t.scrollWidth - 2);
}
function scrollTabs(dir) {
  var t = document.getElementById("date_tabs");
  if (t) t.scrollBy({ left: dir * Math.max(200, t.clientWidth * 0.8), behavior: "smooth" });
}
$(document).on("shiny:value", function (e) {
  if (e.name !== "trip_tabs") return;
  setTimeout(function () {
    var t = document.getElementById("date_tabs");
    if (!t) return;
    var active = t.querySelector(".active");
    if (active) t.scrollLeft = Math.max(0, active.offsetLeft - t.clientWidth / 2 + active.clientWidth / 2);
    t.addEventListener("scroll", updateTabArrows, { passive: true });
    t.addEventListener("wheel", function (ev) {
      if (Math.abs(ev.deltaY) > Math.abs(ev.deltaX)) { t.scrollLeft += ev.deltaY; ev.preventDefault(); }
    }, { passive: false });
    updateTabArrows();
  }, 0);
});
window.addEventListener("resize", updateTabArrows);

// Trip settings sheet (the top-bar button). `target` is a section ("import", "examples", "export"):
// it is scrolled into view and flashes briefly.
function openFreeTimes(target) {
  document.body.classList.add("sheet-open");
  var body = document.querySelector("#free_sheet .sheet-body");
  if (!target) { if (body) body.scrollTop = 0; return; }
  var el = document.getElementById("ft-" + target);
  if (el) setTimeout(function () {
    el.scrollIntoView({ behavior: "smooth", block: "center" });
