    var bar = strip.querySelector('.strip-free[data-wid="' + h.dataset.wid + '"]');
    var mate = strip.querySelector('.free-handle[data-wid="' + h.dataset.wid + '"]:not([data-field="' + h.dataset.field + '"])');
    if (!bar || !mate) return;
    var a = h.dataset.field === "t0" ? t : +mate.dataset.t, b = h.dataset.field === "t0" ? +mate.dataset.t : t;
    bar.style.left = pct(a);
