          { id: "buildings", type: "fill-extrusion", source: "buildings",
            paint: { "fill-extrusion-color": BUILDING, "fill-extrusion-height": ["get", "h"],
                     "fill-extrusion-base": ["get", "b"], "fill-extrusion-opacity": 0.93,
                     "fill-extrusion-vertical-gradient": true } }
        ]
      },
      center: [144.9631, -37.8150], zoom: 15.4, pitch: 58, bearing: -20, maxPitch: 75, attributionControl: false
    });
    map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "top-right");   // 2D / 3D switch is top left
    map.addControl(new maplibregl.AttributionControl({ compact: true }), "bottom-left");
    map.on("load", function () {
      // keep the credits as the small (i) button so they do not cover the legend
      var attrib = document.querySelector("#map3d .maplibregl-ctrl-attrib");
      if (attrib) attrib.classList.remove("maplibregl-compact-show");
      map.setLight({ anchor: "map", position: [1.5, 200, 35], intensity: 0.4 });
      map.addSource("route", { type: "geojson", data: emptyFc() });
      map.addLayer({ id: "route-casing", type: "line", source: "route",
                     layout: { "line-join": "round", "line-cap": "round" },
                     paint: { "line-color": "#ffffff", "line-width": 9, "line-opacity": 0.95 } });
      map.addLayer({ id: "route", type: "line", source: "route", filter: ["!=", ["get", "back"], true],
                     layout: { "line-join": "round", "line-cap": "round" },
