    var expr = ["match", ["get", "place"]];
    msg.stops.forEach(function (s) { if (s.building) expr.push(s.id, s.color); });
    map.setPaintProperty("buildings", "fill-extrusion-color", expr.length > 2 ? expr.concat([BUILDING]) : BUILDING);
    // numbered stops, start and end
    markers.forEach(function (m) { m.remove(); });
    markers = [];
    msg.ends.forEach(function (e) {
      markers.push(new maplibregl.Marker({ element: pin("end3d " + e.kind, "", e.label) })
        .setLngLat([e.lon, e.lat]).addTo(map));
    });
    msg.stops.forEach(function (s) {
      var el = pin("pin3d" + (s.problem ? " problem" : "") + (s.dark ? " dark" : ""),
                   s.n + "<span>" + s.name + "</span>", s.label, function () {
        Shiny.setInputValue("focus_place", s.id, { priority: "event" });
      });
      el.style.background = s.color;
      markers.push(new maplibregl.Marker({ element: el, anchor: "center" }).setLngLat([s.lon, s.lat]).addTo(map));
    });
    if ((refit || msg.refit) && msg.fit) {
      map.fitBounds([[msg.fit[0], msg.fit[1]], [msg.fit[2], msg.fit[3]]],
                    { padding: { top: 70, bottom: 80, left: 60, right: 60 }, pitch: 58, bearing: -20,
                      duration: refit ? 0 : 800, maxZoom: msg.stops.length ? 16.6 : 15.4 });
    }
  }

  function show(on) {
    visible = on;
    var planner = document.querySelector(".planner");
    if (planner) planner.classList.toggle("mode-3d", on);
    document.querySelectorAll(".map-controls button").forEach(function (b) {
      b.classList.toggle("active", b.dataset.mode === (on ? "3d" : "2d"));
    });
    if (!on) { dispatchEvent(new Event("resize")); return; }
    init();
    map.resize();
    if (ready && latest) render(latest, true);
    if (ready) showPopup(latestPopup);
  }

  Shiny.addCustomMessageHandler("map3d", function (msg) {
    latest = msg;
    if (visible && ready) render(msg, false);
  });
  Shiny.addCustomMessageHandler("map3d-show", show);
  Shiny.addCustomMessageHandler("map3d-popup", function (msg) {
    latestPopup = msg;
    if (map) showPopup(msg);
  });
})();

/* Melbourne in N Hours — visual design taken from the Figma Make prototype
   (01_分析与计划/Figma_design_prompt_2026-10-21.md): Apple-calm layout, Nintendo-friendly controls.
   Desktop first; tablet and phone breakpoints at the end.
   Colour roles: blue (--brand) = things you can act on and your plan (buttons, selection, route);
   orange = data (street busyness, its complement, so the two never get confused and stay
   colour-blind safe); red only for problems. */

:root {
  --brand: #0071e3;          /* white text on it: 4.6:1 */
  --brand-dark: #0058b0;
  --brand-soft: #e8f2fd;
  --blue: var(--brand);
  --yellow: #ffcc00;
  --ink: #1d1d1f;
  --ink2: #6e6e73;
  --ink3: #aeaeb2;
  --canvas: #f5f5f7;
  --surface: #fff;
  --line: #e5e5ea;
  --glass: rgba(255, 255, 255, .78);
  --ok: #34c759;
  --ok-bg: #eaf8ee;
  --warn: #ff9f0a;
  --warn-bg: #fff5e5;
  --bad: #d70015;
  --bad-bg: #fdecee;
  --quiet: #fde2c4;
  --moderate: #f59e4c;
  --busy: #c2410c;
  --open: #334155;
  --nofit: #94a3b8;
  --r-input: 10px;
  --r-card: 16px;
  --r-sheet: 24px;
  --r-pill: 999px;
  --shadow: 0 1px 2px rgba(0, 0, 0, .06), 0 8px 24px rgba(0, 0, 0, .06);
  --floating: 0 12px 32px rgba(0, 0, 0, .12);
}

* { box-sizing: border-box; }
html, body { height: 100%; }
/* Chinese falls back to the system's own fonts (PingFang on Apple, Microsoft YaHei on Windows) */
body { margin: 0; background: var(--canvas); color: var(--ink); font: 14px/20px Inter, system-ui, -apple-system, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", sans-serif; }
.container-fluid { padding: 0; }
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
h1, h2, h3, p { margin: 0; }
h1, h2, h3, .brand strong { font-family: Nunito, Inter, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", sans-serif; }
/* Trip settings: the language switch */
.lang-switch { display: flex; gap: 6px; }
.lang-switch button {
  flex: 1; min-height: 40px; border: 1px solid var(--line); background: #fff; border-radius: var(--r-pill);
  font-weight: 600; cursor: pointer;
}
.lang-switch button.active { background: var(--brand); border-color: var(--brand); color: #fff; }
.lang-card .card-icon { font: 800 13px/1 Nunito, sans-serif; }
h1 { font-size: 28px; line-height: 34px; font-weight: 800; letter-spacing: -.5px; }
h2 { font-size: 18px; line-height: 24px; font-weight: 800; }
h3 { font-size: 15px; line-height: 20px; font-weight: 800; }
.card-icon svg, .dropzone svg, .btn svg, .route svg, .status > svg, .nav-overview svg, .calendar-bar-icon svg {
  width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round;
}

.map-area, .es-map { isolation: isolate; }   /* a map's controls never rise above the top bar's menu */
.app { display: grid; height: 100vh; overflow: hidden; grid-template-rows: 76px minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); }
.topbar { min-width: 0; }
.views { min-height: 0; position: relative; }
.view { height: 100%; min-height: 0; overflow: auto; }
.view-day { overflow: hidden; }

/* ---- top bar ---- */
.topbar {
  background: rgba(255, 255, 255, .9); border-bottom: 1px solid var(--line); backdrop-filter: blur(20px);
  display: flex; align-items: center; padding: 0 32px; gap: 32px; z-index: 1500; position: relative;
}
.brand { border: 0; background: none; display: flex; align-items: center; gap: 10px; white-space: nowrap; cursor: pointer; padding: 0; }
.brand > span {
  background: var(--brand); color: #fff; width: 36px; height: 36px; border-radius: 11px;
  display: grid; place-items: center; font: 800 22px Nunito, sans-serif;
}
.brand strong { font-size: 16px; font-weight: 800; }
.trip-tabs { display: flex; gap: 6px; overflow: auto; flex: 1; scrollbar-width: none; }
.trip-tabs button {
  height: 48px; padding: 0 14px; border: 0; background: transparent; border-radius: 12px; display: flex; align-items: center;
  gap: 6px; white-space: nowrap; cursor: pointer; font-weight: 600; color: var(--ink2);
}
.trip-tabs button:hover { background: var(--canvas); }
.trip-tabs button small { font-size: 12px; color: var(--ink2); }
.trip-tabs button i {
  font-style: normal; background: var(--line); font-size: 11px; min-width: 18px; height: 18px; border-radius: 9px;
  display: grid; place-items: center; padding: 0 4px;
}
.trip-tabs button.active { background: var(--brand-soft); color: var(--brand-dark); }
.trip-tabs button.active i { background: var(--brand); color: #fff; }
.trip-tabs .nav-overview svg { width: 18px; height: 18px; }
.nav-settings {
  flex: none; height: 40px; padding: 0 14px; border: 1px solid var(--line); background: #fff; border-radius: var(--r-pill);
  display: flex; align-items: center; gap: 7px; font-weight: 600; color: var(--ink); cursor: pointer; white-space: nowrap;
}
.nav-settings:hover { border-color: var(--brand); color: var(--brand-dark); }
.nav-settings svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.nav-divider { width: 1px; height: 28px; background: var(--line); flex: none; }
/* a free-time tab: date (and how many places are planned) over the hours */
.date-tabs button { flex-direction: column; align-items: flex-start; justify-content: center; gap: 1px; padding: 0 12px; line-height: 1.25; }
.date-tabs .tab-date { display: flex; align-items: center; gap: 5px; font-size: 13px; }
.date-tabs button small { font-size: 12px; font-weight: 500; }
.date-tabs button i { height: 16px; min-width: 16px; font-size: 11px; }

/* ---- pages ---- */
.page { max-width: 1376px; margin: auto; padding: 48px 32px 72px; }
.page-lead { padding-bottom: 0; }
.page-follow { padding-top: 0; }
.page-title > p:last-child { color: var(--ink2); margin-top: 6px; }
.eyebrow { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--brand); font-weight: 700; margin-bottom: 6px !important; }

/* form fields (Shiny inputs styled like the Figma fields) */
.shiny-input-container:not(.shiny-input-container-inline) { width: 100% !important; max-width: 100%; }
.form-group { margin-bottom: 0; }
.control-label { font-size: 12px; color: var(--ink2); font-weight: 600; margin-bottom: 5px; }
.selectize-input, .form-control {
  min-height: 42px; border: 1px solid var(--line); border-radius: var(--r-input); background: #fff; box-shadow: none;
  padding: 10px 12px; font-size: 13px;
}
.selectize-input.focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(0, 113, 227, .15); }
.selectize-dropdown { font-size: 13px; border-radius: var(--r-input); }
.input-daterange .input-group-addon { border: 0; background: none; }
.checkbox { margin: 6px 0; }
.checkbox label { font-size: 12px; }
.two-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }

/* buttons */
.btn {
  border-radius: var(--r-pill); border: 0; min-height: 44px; padding: 0 18px; display: inline-flex; align-items: center;
  justify-content: center; gap: 8px; font-weight: 700; cursor: pointer; transition: .2s transform, .2s box-shadow; font-size: 14px;
}
.btn:hover { transform: translateY(-1px); box-shadow: 0 6px 18px rgba(0, 113, 227, .18); }
.btn.primary { background: var(--brand); color: #fff; }
.btn.primary:hover, .btn.primary:focus { color: #fff; background: var(--brand-dark); }
.btn.secondary { background: #fff; border: 1px solid var(--line); color: var(--ink); text-decoration: none; }
.btn.danger { color: var(--bad); }

/* ---- free-time settings: cards in the sheet ---- */
.setup-card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-sheet); padding: 24px;
  box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 16px;
}
.setup-card.featured { border-top: 3px solid var(--brand); }
.setup-card > p { color: var(--ink2); margin-top: -10px; }
.card-icon { width: 44px; height: 44px; border-radius: 14px; background: var(--brand-soft); color: var(--brand); display: grid; place-items: center; }
.card-icon.blue { background: var(--canvas); color: var(--ink); }
.card-icon.yellow { background: #fff8d6; color: #8a6d00; font-size: 20px; }
.dropzone {
  border: 1.5px dashed var(--ink3); background: var(--canvas); border-radius: 14px; min-height: 116px; padding: 14px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; color: var(--ink2); text-align: center;
}
.dropzone svg { color: var(--brand); }
.dropzone strong { color: var(--ink); }
.dropzone > span { font-size: 12px; }
.dropzone .shiny-input-container { width: auto !important; margin-top: 4px; }
.dropzone .input-group { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.dropzone .input-group-btn .btn { background: none; border: 0; color: var(--blue); font-weight: 600; min-height: 0; padding: 0; box-shadow: none; transform: none; }
.dropzone .form-control { border: 0; background: transparent; text-align: center; min-height: 0; height: auto; padding: 0; font-size: 12px; color: var(--ink2); }
.dropzone .progress { margin: 4px auto 0; height: 4px; width: 160px; }
.setup-card > .btn { margin-top: 4px; }
.persona {
  border: 1px solid var(--line); background: #fff; border-radius: 14px; padding: 12px; display: flex; align-items: center;
  text-align: left; gap: 12px; min-height: 64px; cursor: pointer; width: 100%;
}
.persona:hover { border-color: var(--blue); background: #f2f8ff; }
.persona-icon { width: 36px; height: 36px; background: var(--canvas); border-radius: 11px; display: grid; place-items: center; flex: none; }
.persona > span:nth-child(2) { display: flex; flex-direction: column; flex: 1; }
.persona small { color: var(--ink2); }
.persona b { font-size: 22px; color: var(--ink3); }
.found { margin-top: 40px; }
.section-title { display: flex; justify-content: space-between; align-items: end; margin-bottom: 16px; gap: 16px; }
.section-title p { color: var(--ink2); }
.found-list { background: #fff; border: 1px solid var(--line); border-radius: var(--r-card); box-shadow: var(--shadow); }
.found-row {
  display: grid; grid-template-columns: 110px 170px 1fr 44px; align-items: center; min-height: 74px; padding: 8px 16px;
  border-bottom: 1px solid var(--line);
}
.found-row:last-child { border: 0; }
.found-row > div { display: flex; flex-direction: column; }
.found-row span { color: var(--ink2); font-size: 12px; }
.date-box strong { color: var(--brand); font-size: 16px; }
.found-row .route { flex-direction: row; gap: 8px; align-items: center; }
.route svg { color: var(--blue); flex: none; }
.found-row > button { border: 0; background: none; font-size: 20px; color: var(--ink2); min-height: 44px; cursor: pointer; }
.found-row > button:hover { color: var(--bad); }

/* ---- 2. overview (home page) ---- */
.walk-tag { font-size: 12px; color: var(--brand-dark); background: var(--brand-soft); border-radius: 6px; padding: 1px 7px; }
/* how tiring (R/effort.R): three bars, filled up to the level, then the label and the steps */
.effort { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 600; color: var(--ink); white-space: nowrap; }
.effort i { display: inline-flex; align-items: flex-end; gap: 2px; height: 12px; }
.effort i b { width: 4px; border-radius: 1px; background: var(--line); }
.effort i b:nth-child(1) { height: 5px; }
.effort i b:nth-child(2) { height: 8px; }
.effort i b:nth-child(3) { height: 12px; }
.effort.e1 i b:nth-child(1), .effort.e2 i b:nth-child(-n+2), .effort.e3 i b { background: var(--ink); }
.effort small { font-weight: 400; color: var(--ink2); font-size: 12px; }
.place-body > p.place-effort { font-size: 12px; }
.itinerary-effort { margin: 0 0 6px; }
.trip-total { color: var(--ink); }
.itinerary > .part-row {
  font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--ink2);
  padding: 8px 0 2px 44px; border-top: 1px solid var(--line); margin-top: 4px;
}
.itinerary > .part-row:first-child { border-top: 0; margin-top: 0; }
.page-credit { font-size: 12px; color: var(--ink2); margin-top: 12px; }

/* ---- 3. one free time: places | map card | plan ---- */
.planner {
  height: 100%; display: grid; grid-template-columns: 290px minmax(0, 1fr) 340px; gap: 14px; padding: 14px;
  overflow: hidden;
}
.place-panel, .plan-panel {
  min-height: 0; overflow: auto; background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r-sheet); box-shadow: var(--shadow);
}
.place-panel { padding: 14px; }
.plan-panel { padding: 16px; }
.map-area {
  position: relative; min-height: 0; border-radius: var(--r-sheet); overflow: hidden; border: 1px solid var(--line);
  box-shadow: var(--shadow); background: #e9e5de;
}
.map-area #map { position: absolute !important; inset: 0; height: 100% !important; background: #e9e5de; }
.map-area .leaflet-tile-pane { filter: grayscale(.8) brightness(1.06) contrast(.85); }   /* same greying as the 3D view (map3d.js) */
.map-legend {
  position: absolute; z-index: 600; left: 50%; transform: translateX(-50%); bottom: 18px; background: var(--glass);
  backdrop-filter: blur(10px); padding: 8px 14px; border-radius: var(--r-pill); display: flex; gap: 10px; font-size: 12px;
  box-shadow: var(--shadow); white-space: nowrap;
}
.map-legend small { color: var(--ink2); font-weight: 400; margin-left: 2px; }
.map-legend .legend-unit { color: var(--ink2); }
.map-area .leaflet-control-scale, .es-map .leaflet-control-scale { margin-top: 8px; }
.map-legend span { display: flex; align-items: center; gap: 4px; }
.map-legend i { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.map-legend i.ring { width: 10px; height: 10px; border: 2px dashed var(--ok); }
.stop-num { color: var(--ink) !important; font-weight: 800; font-size: 12px; }
.stop-num.dark { color: #fff !important; }
.leaflet-tooltip.stop-num { background: transparent; border: none; box-shadow: none; }

/* place card + list (left) */
.place-card { position: relative; background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-card); box-shadow: var(--shadow); margin-bottom: 12px; }
.place-body { padding: 12px; display: flex; flex-direction: column; gap: 7px; }
.place-body h2 { font-size: 17px; line-height: 22px; padding-right: 30px; }
.place-body .eyebrow { padding-right: 34px; }
.place-body > p { font-size: 12px; line-height: 16px; }
.place-body > p b { color: #27833b; }
.closed-text { color: var(--bad); font-weight: 700; }
.tags { display: flex; gap: 5px; flex-wrap: wrap; }
.tags span { background: var(--canvas); border-radius: var(--r-pill); padding: 2px 7px; font-size: 12px; }
.card-actions { display: flex; gap: 6px; }
.card-actions .btn { font-size: 12px; padding: 0 10px; min-height: 36px; flex: 1; }
.filters { padding: 4px 2px 6px; }
.filters h3 { margin-bottom: 4px; }
.chips { display: flex; flex-direction: column; align-items: stretch; gap: 6px; }
.chips > strong { font-size: 12px; color: var(--ink2); margin-top: 6px; text-transform: none; }
/* one row per place: the name adds it to this day (or takes it out), the i opens its popup on the map */
.pick { display: flex; align-items: stretch; border: 1px solid var(--line); background: #fff; border-radius: 12px; min-height: 36px; }
.pick:hover { border-color: var(--blue); }
.pick-main {
  flex: 1; min-width: 0; border: 0; background: none; padding: 6px 4px 6px 10px; font-size: 12px; text-align: left;
  display: flex; align-items: center; gap: 6px; cursor: pointer; border-radius: 12px 0 0 12px;
}
.pick-main span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.pick-main b { color: var(--brand); font-size: 14px; width: 18px; text-align: center; flex: none; }
.pick-main i {
  font-style: normal; background: var(--blue); color: #fff; width: 18px; height: 18px; border-radius: 50%;
  display: inline-grid; place-items: center; font-size: 11px; flex: none;
}
.pick-main small { color: var(--ink2); margin-left: auto; padding-left: 6px; white-space: nowrap; }
.pick-info {
  flex: none; width: 34px; border: 0; border-left: 1px solid var(--line); background: none; color: var(--ink2);
  font: italic 700 12px/1 Georgia, serif; cursor: pointer; border-radius: 0 12px 12px 0;
}
.pick-info:hover { background: var(--brand-soft); color: var(--brand-dark); }
.pick.selected { background: #e8f3ff; border-color: var(--blue); }
.pick.selected .pick-main { color: var(--brand-dark); font-weight: 600; }
.pick.moved .pick-main small { color: var(--brand-dark); }
.pick.unfit .pick-main { color: var(--ink2); }
.pick.unfit .pick-main b { color: var(--ink2); }
.pick.unfit .pick-main small { color: #9b5f00; }
/* the popup about a place, on the 2D and the 3D map */
.place-popup .leaflet-popup-content-wrapper, .place-popup .maplibregl-popup-content { border-radius: var(--r-card); padding: 0; box-shadow: var(--floating); }
.place-popup .leaflet-popup-content { margin: 0; width: 280px !important; }
.place-popup .maplibregl-popup-content { width: 280px; }
.place-popup .place-card { border: 0; box-shadow: none; margin: 0; background: transparent; }
.place-popup .leaflet-popup-content p, .place-popup .maplibregl-popup-content p { margin: 0; }
.place-popup .place-body h2 { padding-right: 24px; }
.place-popup .leaflet-popup-close-button, .place-popup .maplibregl-popup-close-button { top: 8px; right: 8px; font-size: 20px; width: 26px; height: 26px; }

/* plan (right) */
.plan-date { display: flex; align-items: center; justify-content: space-between; padding-bottom: 10px; border-bottom: 1px solid var(--line); }
.plan-date p { font-size: 12px; color: var(--ink2); }
.plan-date h2 { font-size: 18px; }
.plan-date > span { background: var(--ok-bg); color: #237c37; border-radius: var(--r-pill); padding: 4px 8px; font-size: 12px; font-weight: 700; white-space: nowrap; }
.plan-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 12px 0; }
.plan-fields .shiny-input-container:last-child { grid-column: 1 / -1; }
.plan-fields .control-label { font-size: 12px; margin-bottom: 3px; }
.plan-fields .selectize-input { min-height: 36px; padding: 7px 9px; font-size: 12px; }
.status { border-radius: 14px; padding: 10px; display: flex; gap: 9px; background: var(--canvas); color: var(--ink2); }
.status > svg { flex: none; }
.status strong { font-size: 12px; display: block; }
.status p { font-size: 12px; line-height: 16px; }
.status.ok { background: var(--ok-bg); color: #237c37; }
.status.warn { background: var(--warn-bg); color: #7a4a00; }
.status.bad { background: var(--bad-bg); color: var(--bad); }
.status button {
  border: 1px solid currentColor; background: rgba(255, 255, 255, .6); border-radius: var(--r-pill); padding: 3px 8px;
  margin: 7px 4px 0 0; font-size: 12px; font-weight: 700; cursor: pointer; color: inherit;
}
.tip {
  width: 100%; border: 1px solid #cfdfef; background: #f3f8fd; border-radius: 14px; padding: 8px 10px; margin: 8px 0 0;
  display: flex; align-items: center; text-align: left; gap: 8px; cursor: pointer;
}
.tip > span { color: var(--blue); }
.tip > div { display: flex; flex: 1; flex-direction: column; }
.tip strong { font-size: 12px; }
.tip small { color: var(--ink2); font-size: 12px; }
.tip > b { color: var(--blue); font-size: 12px; white-space: nowrap; }
.plan-panel h3 { font-size: 12.5px; margin: 14px 0 6px; }
.options { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.options button {
  border: 1px solid var(--line); background: #fff; border-radius: 12px; padding: 8px 9px; text-align: left;
  display: flex; flex-direction: column; cursor: pointer;
}
.options button.selected { border: 2px solid var(--blue); background: #f5faff; padding: 7px 8px; }
.options span { display: flex; justify-content: space-between; gap: 4px; align-items: baseline; }
.options span strong { font-size: 12px; line-height: 16px; }
.options i { font-style: normal; font-size: 11px; color: var(--blue); white-space: nowrap; }
.options b { font-size: 18px; line-height: 24px; font-family: Nunito, Inter, sans-serif; }
.options button.bad b { color: var(--bad); }
.options small { font-size: 12px; line-height: 16px; color: var(--ink2); }
.opt-note { align-self: center; color: var(--ink2); font-size: 12px; }
.itinerary-head { display: flex; justify-content: space-between; align-items: center; margin: 14px 0 2px; }
.itinerary-head h3 { margin: 0 !important; }
.itinerary-head span { font-size: 12px; color: var(--ink2); }
.itinerary > button {
  border: 0; background: none; width: 100%; display: grid; grid-template-columns: 38px 24px 1fr; gap: 6px; text-align: left;
  min-height: 44px; padding: 4px 0; cursor: pointer; border-radius: 8px;
}
.itinerary > button:hover { background: rgba(10, 132, 255, .06); }
.itinerary time { font-size: 12px; color: var(--ink2); font-variant-numeric: tabular-nums; padding-top: 2px; }
.itinerary > button > i {
  width: 22px; height: 22px; background: var(--moderate); border: 2px solid #fff; border-radius: 50%; font-style: normal;
  display: grid; place-items: center; font-size: 11px; font-weight: 700;
}
.itinerary > button.start > i { background: #fff; box-shadow: 0 0 0 2px var(--ink); width: 14px; height: 14px; margin: 4px; }
.itinerary > button > i.done { background: var(--ok); box-shadow: 0 0 0 1px var(--ok); color: #fff; }
.itinerary > button > i.late { background: var(--bad); box-shadow: 0 0 0 1px var(--bad); color: #fff; }
.itinerary > button > span { display: flex; flex-direction: column; line-height: 1.3; }
.itinerary strong { font-size: 12px; }
.itinerary > button.bad strong { color: var(--bad); }
.itinerary small { color: var(--ink2); font-size: 12px; }
.itinerary small.note { color: var(--bad); }
.itinerary em { font-style: normal; color: var(--blue); font-size: 12px; margin-top: 3px; }
.still-fits { border-top: 1px solid var(--line); padding-top: 4px; margin-top: 8px; }
.still-fits button { width: 100%; border: 0; background: none; text-align: left; padding: 5px 0; font-size: 12px; cursor: pointer; }
.still-fits button span { float: right; color: var(--blue); font-weight: 700; }
.credits { font-size: 12px; line-height: 16px; color: var(--ink2); margin-top: 12px; }

/* notifications as Figma toasts */
#shiny-notification-panel { left: 50%; right: auto; bottom: 30px; transform: translateX(-50%); width: auto; max-width: 520px; }
.shiny-notification {
  background: var(--ink); color: #fff; border: 0; border-radius: var(--r-pill); padding: 10px 18px; box-shadow: var(--floating);
  opacity: 1; font-size: 13px;
}
.shiny-notification-warning { background: #7a4a00; }
.shiny-notification-error { background: var(--bad); }
.shiny-notification-close { color: #fff; }

/* example notice (first visit) and small hints */
.hint { font-size: 12px; color: var(--ink2); margin-top: -6px; }
.hint a { color: var(--blue); font-weight: 600; }
/* the card above the days: where the free times come from + the gear */
.calendar-bar {
  margin: 20px 0 0; border: 1px solid var(--line); background: #fff; border-radius: 14px; padding: 12px 14px;
  display: flex; align-items: center; gap: 12px; box-shadow: var(--shadow);
}
.calendar-bar.example { border-color: #cfdfef; background: #f3f8fd; }
.calendar-bar-icon {
  width: 36px; height: 36px; border-radius: 11px; background: var(--brand-soft); color: var(--brand); display: grid;
  place-items: center; flex: none; font-size: 17px;
}
.calendar-bar.example .calendar-bar-icon { background: #fff; }
.calendar-bar > div { flex: 1; min-width: 0; }
.calendar-bar strong { display: block; }
.calendar-bar p { color: var(--ink2); font-size: 12.5px; }
.calendar-bar .btn { min-height: 38px; white-space: nowrap; font-size: 13px; }
.btn.gear svg { width: 18px; height: 18px; }
.empty-state { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 28px; }

/* ---- free-time settings sheet (slides in from the right, www/app.js) ---- */
.sheet-backdrop {
  position: fixed; inset: 0; background: rgba(15, 23, 42, .28); opacity: 0; pointer-events: none;
  transition: opacity .2s; z-index: 2000;
}
.sheet {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(540px, 100vw); background: var(--canvas); z-index: 2001;
  display: flex; flex-direction: column; box-shadow: var(--floating); transform: translateX(105%); transition: transform .25s ease;
  visibility: hidden;
}
body.sheet-open .sheet { transform: none; visibility: visible; }
body.sheet-open .sheet-backdrop { opacity: 1; pointer-events: auto; }
.sheet-head {
  display: flex; align-items: center; gap: 12px; padding: 16px 20px; background: #fff; border-bottom: 1px solid var(--line);
}
.sheet-head > div:nth-child(2) { flex: 1; }
.sheet-head p { color: var(--ink2); font-size: 12.5px; }
.sheet-close {
  width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line); background: #fff; font-size: 20px;
  line-height: 1; cursor: pointer; color: var(--ink2); flex: none;
}
.sheet-close:hover { color: var(--ink); border-color: var(--ink3); }
.sheet-body { flex: 1; overflow: auto; padding: 18px 20px 48px; display: flex; flex-direction: column; gap: 16px; }
.sheet .setup-card { padding: 18px; gap: 12px; border-radius: var(--r-card); }
.sheet .setup-card .shiny-input-container { width: 100%; margin-bottom: 0; }
.sheet .setup-card > .btn { align-self: flex-start; }
.sheet-card-head { display: flex; align-items: center; gap: 12px; }
.sheet-card-head p { color: var(--ink2); font-size: 12.5px; margin-top: 2px; }
.sheet-card-head .card-icon { width: 36px; height: 36px; border-radius: 11px; flex: none; }
.sheet .found { margin-top: 0; }
.sheet .section-title { margin-bottom: 10px; align-items: start; }
.sheet .found-row {
  grid-template-columns: 70px minmax(0, 1fr) 36px; grid-template-rows: auto auto; row-gap: 6px; padding: 10px 12px; min-height: 0;
}
.sheet .found-row .date-box { grid-row: 1 / span 2; }
.sheet .found-row .route { grid-column: 2 / span 2; grid-row: 2; }
.sheet .found-row > button { grid-column: 3; grid-row: 1; min-height: 32px; }
.sheet .found-row .route .inline-select { max-width: none; flex: 1; min-width: 0; }
.export-links { display: flex; gap: 10px; flex-wrap: wrap; }
.export-links .btn { min-height: 40px; font-size: 13px; }
.found-row.flash, .setup-card.flash { animation: flash 1.8s ease; }
@keyframes flash { 0%, 45% { background: var(--brand-soft); } 100% { background: #fff; } }

/* free-time tabs in the top bar scroll sideways, with arrows when they do not all fit */
.trip-tabs { overflow: visible; min-width: 0; align-items: center; }
.date-strip { position: relative; flex: 1; min-width: 0; display: flex; align-items: center; }
.date-tabs { position: relative; display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; flex: 1; min-width: 0; scroll-behavior: smooth; }
.date-tabs::-webkit-scrollbar { display: none; }
.trip-tabs .strip-arrow {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 2; width: 32px; height: 32px; padding: 0;
  border-radius: 50%; border: 1px solid var(--line); background: #fff; box-shadow: var(--shadow); font-size: 18px;
  color: var(--ink); display: none; place-items: center;
}
.trip-tabs .strip-arrow.left { left: -2px; }
.trip-tabs .strip-arrow.right { right: -2px; }
.date-strip.can-left .strip-arrow.left, .date-strip.can-right .strip-arrow.right { display: grid; }
.date-strip.can-left .date-tabs { -webkit-mask-image: linear-gradient(90deg, transparent, #000 44px); mask-image: linear-gradient(90deg, transparent, #000 44px); }
.date-strip.can-right .date-tabs { -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 44px), transparent); mask-image: linear-gradient(90deg, #000 calc(100% - 44px), transparent); }
.date-strip.can-left.can-right .date-tabs {
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 44px, #000 calc(100% - 44px), transparent);
  mask-image: linear-gradient(90deg, transparent, #000 44px, #000 calc(100% - 44px), transparent);
}

/* free-time list: times and places changed in place */
.found-row { grid-template-columns: 110px 200px 1fr 44px; }
.inline-times { display: flex; align-items: center; gap: 4px; margin-bottom: 2px; }
.inline-select {
  border: 1px solid var(--line); border-radius: 8px; background: #fff; padding: 4px 6px; font-size: 12.5px; font-weight: 600;
  max-width: 100%; cursor: pointer; color: var(--ink);
}
.inline-select:hover { border-color: var(--blue); }
.found-row .route .inline-select { font-weight: 500; max-width: 44%; }

/* rest first (day page) */
.rest { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; margin: 10px 0 0; }
.rest-label { font-size: 12px; font-weight: 700; color: var(--ink2); margin-right: 2px; }
.rest button { border: 1px solid var(--line); background: #fff; border-radius: var(--r-pill); padding: 3px 7px; font-size: 12px; cursor: pointer; }
.rest button:hover { border-color: var(--blue); }
.rest button.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.rest small { width: 100%; color: var(--ink2); font-size: 12px; }
.itinerary > button.rest-row > i { background: #fff8d6; box-shadow: 0 0 0 1px #f3d36b; font-size: 11px; }

/* 2D / 3D map */
.map3d { position: absolute; inset: 0; display: none; background: #e9e5de; }
.planner.mode-3d .map3d { display: block; }
.planner.mode-3d #map { display: none; }
.map-controls {
  position: absolute; z-index: 650; left: 14px; top: 14px; background: var(--glass); backdrop-filter: blur(10px);
  padding: 4px; border-radius: var(--r-pill); box-shadow: var(--shadow); display: flex; gap: 2px;
}
.map-controls button { border: 0; background: none; border-radius: var(--r-pill); padding: 6px 12px; font-weight: 700; font-size: 12px; cursor: pointer; }
.map-controls button.active { background: var(--ink); color: #fff; }
.pin3d {
  width: 34px; height: 34px; border-radius: 50%; border: 3px solid #fff; box-shadow: 0 3px 10px rgba(0, 0, 0, .25);
  font-weight: 800; font-size: 13px; color: var(--ink); cursor: pointer; padding: 0; transition: transform .2s;
}
.pin3d.dark { color: #fff; }
.pin3d.problem { box-shadow: 0 0 0 3px var(--bad), 0 3px 10px rgba(0, 0, 0, .25); }
.pin3d:hover { transform: scale(1.12); }
.pin3d span {
  position: absolute; top: 36px; left: 50%; transform: translateX(-50%); background: var(--glass); backdrop-filter: blur(8px);
  white-space: nowrap; border-radius: 8px; padding: 2px 6px; font-size: 11px; font-weight: 600; color: var(--ink); pointer-events: none;
}
.end3d { width: 16px; height: 16px; border-radius: 50%; border: 3px solid var(--ink); background: #fff; padding: 0; }
.end3d.end { background: var(--ink); }

/* home page (R/overview.R): the days on the left, the places to go on the right */
.page-home { max-width: 1640px; }
.home {
  display: grid; grid-template-columns: 270px minmax(0, 1fr) 290px; grid-template-areas: "walks days places";
  gap: 16px; margin-top: 20px; align-items: start;
}
.home > .pool-walks { grid-area: walks; }
.home > .days { grid-area: days; }
.home > .pool-places { grid-area: places; }
.days { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-sheet); padding: 20px 22px 16px; box-shadow: var(--shadow); min-width: 0; }
.days-head { display: flex; flex-wrap: wrap; align-items: start; justify-content: space-between; gap: 10px 16px; margin-bottom: 10px; }
.days-head > div:first-child { flex: 1 1 340px; }   /* the buttons go under the text when the column is narrow */
.days-head h2 { font-size: 20px; line-height: 26px; }
.days-head p { color: var(--ink2); margin-top: 3px; font-size: 13px; }
.days-actions { display: flex; gap: 8px; flex: none; }
.days-actions .btn { min-height: 34px; font-size: 13px; padding: 0 14px; white-space: nowrap; }
.day-cols { display: grid; grid-template-columns: 4fr 5fr 5fr; }   /* as long as the parts: 8-12, 12-17, 17-22 */
.day-col { display: flex; flex-direction: column; gap: 6px; min-width: 0; padding: 0 4px; overflow: hidden; }
.day-row { padding: 12px 0; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 8px; }
/* the day's line: date, free time, time on the go, effort, open and settings */
.day-label { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; padding: 0 4px; }
.day-label strong { font-size: 15px; }
.day-label small { font-size: 12px; color: var(--ink2); }
.day-label .effort { flex-wrap: wrap; }
.day-label .effort small { margin-left: 2px; }
.day-open {
  align-self: flex-start; margin-top: 6px; border: 0; background: var(--brand-soft); color: var(--brand-dark); border-radius: var(--r-pill);
  padding: 5px 11px; font-size: 12px; font-weight: 700; cursor: pointer;
}
.day-open:hover { background: #dcebfb; }
.day-buttons { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.day-buttons + .day-buttons { margin-left: 0; }
.day-buttons .day-open { margin-top: 0; }
.day-gear {
  width: 28px; height: 28px; padding: 0; border-radius: 50%; border: 1px solid transparent; background: transparent;
  color: var(--ink2); display: grid; place-items: center; cursor: pointer;
}
.day-gear svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.day-gear:hover { color: var(--ink2); border-color: var(--line); }
.day-track { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.day-strip {
  position: relative; height: 16px; margin: 0 4px 16px; border-radius: 6px;
  background: repeating-linear-gradient(135deg, #ececf0 0 3px, #dcdce2 3px 6px);
}
/* where the parts meet (fixed) and the ends of a free time: dots to drag along the bar, time under each */
.strip-split { top: -3px; bottom: -3px; width: 0; border-left: 1px dashed #9a9aa2; z-index: 1; }
.free-handle {
  position: absolute; top: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px; padding: 0; border-radius: 50%;
  border: 2px solid var(--brand); background: #fff; box-shadow: 0 1px 4px rgba(0, 0, 0, .2); cursor: ew-resize;
  touch-action: none; z-index: 3;
}
.free-handle:hover, .free-handle:focus-visible, .free-handle.dragging { background: var(--brand); transform: scale(1.15); }
.free-handle em {
  position: absolute; top: 18px; left: 50%; transform: translateX(-50%); font: 600 11px/1 Inter, sans-serif;
  font-style: normal; color: var(--brand-dark); white-space: nowrap; pointer-events: none;
}
.days-key .k-handle { width: 12px; height: 12px; border-radius: 50%; border: 2px solid var(--brand); background: #fff; }
.day-strip > i, .strip-band i { position: absolute; }
.strip-free { top: 0; bottom: 5px; background: #fff; border: 1.5px solid #8fb9e6; border-radius: 4px; }
.strip-band { position: absolute; left: 0; right: 0; bottom: 0; height: 5px; }
.strip-band i { top: 0; bottom: 0; }
.strip-band i.lv1 { background: var(--quiet); }
.strip-band i.lv2 { background: var(--moderate); }
.strip-band i.lv3 { background: var(--busy); }
.strip-sun { top: 0; bottom: 0; width: 0; border-left: 2px dashed #b45309; }
.slot {
  border: 1px solid var(--line); border-radius: 14px; padding: 9px 10px; background: #fff; display: flex; flex-direction: column;
  gap: 7px; min-height: 120px; transition: background .15s, border-color .15s, opacity .15s, box-shadow .15s;
}
.slot.empty { border-style: dashed; border-color: #d6d6dc; background: #fbfbfc; }
.slot.tight { border-color: #f3c27a; }
.slot.over { border-color: #f6b3bb; background: #fff8f8; }
.slot.none {
  border: 0; color: var(--ink3); font-size: 12px; align-items: center; justify-content: center; gap: 2px;
  background: repeating-linear-gradient(135deg, #f7f7f9 0 4px, #f0f0f3 4px 8px);
}
.slot.none small { font-size: 12px; }
.slot-head { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }
.slot-head strong { font-size: 12.5px; }
.slot-head span { font-size: 12px; color: var(--ink2); font-variant-numeric: tabular-nums; }
.slot-meter { display: flex; align-items: center; gap: 8px; }
.slot-meter i { flex: 1; height: 6px; background: #eef0f3; border-radius: 3px; position: relative; }
.slot-meter b { position: absolute; left: 0; top: 0; bottom: 0; background: var(--brand); border-radius: 3px; }
.slot-meter u { position: absolute; top: -3px; bottom: -3px; border-left: 2px solid var(--ink); }
.slot-meter small { font-size: 12px; color: var(--ink2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 62%; }
.slot.tight .slot-meter b { background: var(--warn); }
.slot.tight .slot-meter small { color: #7a4a00; }
.slot.over .slot-meter b { background: var(--bad); }
.slot.over .slot-meter small { color: var(--bad); white-space: normal; }
.slot-walk { display: flex; align-items: center; flex-wrap: wrap; gap: 2px 6px; }
.slot-walk span { font-size: 12px; color: var(--brand-dark); background: var(--brand-soft); border-radius: 6px; padding: 1px 6px; }
.slot-walk strong { font-size: 12.5px; flex: 1; min-width: 0; }
.slot-items { display: flex; flex-direction: column; gap: 5px; }
.slot-items > .effort { align-self: flex-end; margin-top: 2px; }
.slot-chip {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto 20px; align-items: center; gap: 6px; background: var(--brand-soft);
  border-radius: 9px; padding: 4px 4px 4px 9px; cursor: grab; font-size: 12px; user-select: none;
}
.slot-chip strong { font-weight: 600; line-height: 1.25; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow-wrap: break-word; }   /* long names wrap to two lines */
.slot-chip small { color: var(--ink2); font-size: 12px; white-space: nowrap; }
/* in a part of a day the name gets the whole first line (two lines at most), time and effort go under it */
.slot .slot-items .slot-chip { grid-template-columns: auto minmax(0, 1fr) 20px; grid-template-areas: "name name x" "dur eff x"; row-gap: 1px; }
.slot .slot-items .slot-chip strong { grid-area: name; }
.slot .slot-items .slot-chip small { grid-area: dur; }
.slot .slot-items .slot-chip .effort { grid-area: eff; }
.slot .slot-items .slot-chip .chip-x { grid-area: x; }
.slot-chip .effort, .pool-item .effort { font-size: 0; gap: 0; }
.chip-x {
  border: 0; background: transparent; color: var(--ink2); font-size: 15px; width: 20px; height: 20px; border-radius: 50%;
  cursor: pointer; line-height: 1; padding: 0; display: grid; place-items: center;
}
.chip-x:hover { background: rgba(0, 0, 0, .07); color: var(--ink); }
.slot-walk .chip-x { margin-left: auto; }
.slot-walk small { flex-basis: 100%; font-size: 12px; color: var(--ink2); }
.slot-suggest {
  border: 1px dashed #b9d3f0; background: #f5f9ff; border-radius: 10px; padding: 8px 9px; display: flex; flex-direction: column; gap: 3px;
}
.slot-suggest small { font-size: 12px; color: var(--ink2); }
.slot-suggest strong { font-size: 13px; }
.slot-suggest > span { font-size: 12px; color: var(--ink2); line-height: 16px; }
.slot-suggest-foot { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
.slot-suggest-foot .btn { min-height: 28px; padding: 0 12px; font-size: 12px; margin-left: auto; }
.slot-hint { color: var(--ink2); font-size: 12px; margin: auto 0; text-align: center; }
.day-any { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 0 4px; }
.day-any > small { font-size: 12px; color: var(--ink2); }
.day-any .slot-chip { grid-template-columns: auto auto auto 20px; }
.days-key { display: flex; gap: 14px; flex-wrap: wrap; margin-top: 12px; }
.days-key span { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--ink2); }
.days-key i { display: inline-block; width: 22px; height: 10px; border-radius: 3px; position: relative; }
.days-key .k-free { background: #fff; border: 1.5px solid #8fb9e6; }
.days-key .k-band { height: 6px; background: linear-gradient(90deg, var(--quiet), var(--moderate), var(--busy)); }
.days-key .k-sun { width: 0; height: 14px; border-left: 2px dashed #b45309; border-radius: 0; }
.days-key .k-meter { height: 6px; background: linear-gradient(90deg, var(--brand) 0 60%, #eef0f3 60%); }
.days-key .k-meter::after { content: ""; position: absolute; left: 75%; top: -3px; bottom: -3px; border-left: 2px solid var(--ink); }
.days-credit { margin-top: 8px; font-size: 12px; color: var(--ink2); }
/* while something is dragged: where it fits (green), fits but tight (amber), cannot go (faded) */
.dragging .slot.drop-ok { border-color: var(--ok); box-shadow: 0 0 0 1px var(--ok) inset; background: var(--ok-bg); }
.dragging .slot.drop-tight { border-color: var(--warn); box-shadow: 0 0 0 1px var(--warn) inset; background: var(--warn-bg); }
.dragging .slot.drop-no { opacity: .4; }
.dragging .slot.drop-here { border-color: var(--brand); border-style: dashed; }
.dragging .slot.over { box-shadow: 0 0 0 3px var(--brand) inset; }
/* a planned place dragged back onto a list (to take it out) */
.dragging-planned .pool.over, .dragging-planned .place-panel.over { box-shadow: 0 0 0 3px var(--brand) inset; }
/* day page: a place dragged from the list into the plan column, or a stop from the plan back onto
   the list. The hint sits at the top of the column that takes it. */
.pick[draggable], .itinerary > button[draggable] { cursor: grab; }
.drop-hint {
  display: none; position: sticky; top: -16px; z-index: 5; margin: -2px 0 10px; padding: 10px 12px; border-radius: 14px;
  align-items: center; gap: 10px; font-size: 12.5px; line-height: 17px; font-weight: 600;
  background: var(--brand-soft); color: var(--brand-dark); border: 1.5px dashed var(--brand);
}
.place-panel .drop-hint { top: -14px; }
.drop-hint b {
  flex: none; width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; font-size: 16px;
  background: var(--brand); color: #fff;
}
.dragging .plan-panel:not(.drop-here) .drop-hint.in, .dragging-planned .place-panel .drop-hint.out { display: flex; }
.dragging .plan-panel.drop-ok { box-shadow: 0 0 0 2px var(--ok) inset; }
.dragging .plan-panel.drop-ok .drop-hint { background: var(--ok-bg); border-color: var(--ok); color: #1c6b31; }
.dragging .plan-panel.drop-ok .drop-hint b { background: var(--ok); }
.dragging .plan-panel.drop-tight { box-shadow: 0 0 0 2px var(--warn) inset; }
.dragging .plan-panel.drop-tight .drop-hint { background: var(--warn-bg); border-color: var(--warn); color: #7a4a00; }
.dragging .plan-panel.drop-tight .drop-hint b { background: var(--warn); }
.dragging .plan-panel.drop-no .drop-hint { background: var(--bad-bg); border-color: #f6b3bb; color: var(--bad); }
.dragging .plan-panel.drop-no .drop-hint b { background: var(--bad); }
.dragging .plan-panel.drop-no > :not(.drop-hint) { opacity: .45; }
.dragging .plan-panel.drop-ok.over { box-shadow: 0 0 0 4px var(--ok) inset; }
.dragging .plan-panel.drop-tight.over { box-shadow: 0 0 0 4px var(--warn) inset; }
.dragging .plan-panel.drop-no.over { box-shadow: 0 0 0 3px #f6b3bb inset; }
.itinerary > button.flash { animation: flash-stop 1.8s ease; }
@keyframes flash-stop { 0%, 45% { background: var(--brand-soft); } 100% { background: transparent; } }
.pool {
  position: sticky; top: 16px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-sheet);
  box-shadow: var(--shadow); display: flex; flex-direction: column; max-height: calc(100vh - 76px - 32px); min-width: 0;
}
.pool-walks .pool-body { padding-top: 10px; }
.pool-head { padding: 18px 18px 12px; border-bottom: 1px solid var(--line); }
.pool-head h2 { font-size: 18px; line-height: 24px; }
.pool-head p { font-size: 12px; color: var(--ink2); margin-top: 3px; }
.pool-filters { display: flex; gap: 6px; margin-top: 10px; }
.pool-filters button { border: 1px solid var(--line); background: #fff; border-radius: var(--r-pill); padding: 4px 11px; font-size: 12px; cursor: pointer; }
.pool-filters button.active { background: var(--brand); border-color: var(--brand); color: #fff; font-weight: 600; }
.pool-body { overflow: auto; padding: 6px 14px 16px; display: flex; flex-direction: column; gap: 6px; min-height: 0; }
.pool-body h3 { font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--ink2); margin: 12px 0 2px; }
.pool-item {
  display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 12px; padding: 8px 8px 8px 10px;
  background: #fff; cursor: grab; user-select: none;
}
.pool-item:hover { border-color: var(--brand); }
.pool-item.pool-walk { border-color: #cfdfef; }
.pool-item.planned { background: #f6f9fd; }
.pool-item.nowhere { opacity: .5; }
.pool-item.filtered { display: none; }
.pool-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.pool-main strong { font-size: 13px; }
.pool-main .walk-tag { margin-left: 6px; }
.pool-stops { font-size: 12px; color: var(--ink2); line-height: 16px; }
.pool-facts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.pool-facts small { font-size: 12px; color: var(--ink2); }
.at-tag { font-size: 12px; font-weight: 700; color: var(--brand-dark); background: var(--brand-soft); border-radius: 6px; padding: 1px 6px; margin-left: 6px; white-space: nowrap; }
.pool-item .add {
  flex: none; width: 30px; height: 30px; border-radius: 50%; border: 1px solid var(--line); background: #fff; font-size: 18px;
  color: var(--brand); cursor: pointer; line-height: 1; padding: 0;
}
.pool-item .add:hover { background: var(--brand); border-color: var(--brand); color: #fff; }

/* ---- tablet ---- */
@media (max-width: 1279px) {
  .topbar { padding: 0 18px; gap: 18px; }
  .brand strong { display: none; }
  .page { padding: 36px 24px; }
  .planner { grid-template-columns: 240px minmax(0, 1fr) 300px; gap: 10px; padding: 10px; }
  .map-legend { display: none; }
}

/* ---- phone: map on top, panels stacked under it ---- */
@media (max-width: 767px) {
  .app { grid-template-rows: auto minmax(0, 1fr); }
  .topbar { display: block; padding: 10px 12px 4px; position: relative; }
  .brand { margin-bottom: 6px; }
  .nav-settings { position: absolute; top: 10px; right: 12px; height: 36px; padding: 0 10px; }
  .nav-settings span { display: none; }
  .brand strong { display: block; }
  .brand > span { width: 32px; height: 32px; }
  .trip-tabs button { height: 40px; padding: 0 10px; }
  .trip-tabs button small { display: none; }
  .page { padding: 24px 16px 56px; }
  .page-title h1 { font-size: 25px; }
  .found-row { grid-template-columns: 80px 1fr 44px; }
  .calendar-bar { flex-wrap: wrap; }
  .calendar-bar > div { flex-basis: calc(100% - 48px); }
  .sheet-body { padding: 14px 12px 40px; }
  .found-row .route { grid-column: 2; }
  .view-day { overflow: auto; }
  .planner { height: auto; overflow: visible; display: flex; flex-direction: column; gap: 12px; padding: 12px; }
  .map-area { order: 1; height: 46vh; flex: none; }
  .plan-panel { order: 2; overflow: visible; }
  .place-panel { order: 3; overflow: visible; }
  .chips { display: grid; grid-template-columns: 1fr 1fr; }
  .chips > strong { grid-column: 1 / -1; }
  .pick { min-height: 44px; }
}

/* home page on smaller screens: the walks and the places share one column beside the days, then
   everything stacks */
@media (max-width: 1279px) {
  .home { grid-template-columns: minmax(0, 1fr) 300px; grid-template-areas: "days walks" "days places"; gap: 14px; }
  .home > .pool { position: static; max-height: 560px; }
}
@media (max-width: 1023px) {
  .home { grid-template-columns: minmax(0, 1fr); grid-template-areas: "days" "walks" "places"; }
  .home > .pool { max-height: none; }
  .pool-body { overflow: visible; }
}
@media (max-width: 767px) {
  .days { padding: 16px 12px; }
  .days-head { flex-direction: column; }
  .day-buttons { margin-left: 0; }
  .day-cols { grid-template-columns: minmax(0, 1fr); gap: 6px; }
  .slot { min-height: 0; }
  .slot.none { display: none; }
}

/* ---- export: the plan as a document (R/export.R), shown over the page as an A4 sheet ---- */
.nav-export { margin-right: -20px; }
.plan-export { margin-top: 12px; }
.plan-export .btn { width: 100%; min-height: 38px; font-size: 13px; }
.days-actions .btn svg { width: 18px; height: 18px; }
.export-view { display: none; position: fixed; inset: 0; z-index: 2000; background: #e8e8ed; flex-direction: column; }
body.export-open .export-view { display: flex; }
.export-bar {
  flex: none; display: flex; align-items: center; gap: 12px; padding: 12px 28px; background: rgba(255, 255, 255, .94);
  border-bottom: 1px solid var(--line); backdrop-filter: blur(20px);
}
.export-bar .btn { min-height: 40px; font-size: 13px; white-space: nowrap; }
.export-title { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.export-title strong { font: 800 17px/22px Nunito, Inter, sans-serif; }
.export-title span { font-size: 12px; color: var(--ink2); }
.export-scope {
  height: 40px; border: 1px solid var(--line); border-radius: var(--r-pill); padding: 0 14px; background: #fff;
  font: 600 13px Inter, sans-serif; color: var(--ink); cursor: pointer; max-width: 260px;
}
.export-save { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.export-save small { font-size: 10.5px; color: var(--ink2); white-space: nowrap; }
.export-scroll { flex: 1; overflow: auto; padding: 32px 0 72px; }

.ex-paper {
  width: 210mm; margin: 0 auto; background: #fff; padding: 14mm; box-shadow: 0 10px 40px rgba(0, 0, 0, .12);
  border-radius: 4px; font-size: 12px; line-height: 1.45; color: var(--ink);
}
.ex-paper a { color: var(--brand-dark); text-decoration: none; }
.ex-paper a:hover { text-decoration: underline; }
.ex-brand { display: flex; align-items: center; gap: 8px; font: 800 13px Nunito, Inter, sans-serif; }
.ex-brand span {
  width: 22px; height: 22px; border-radius: 7px; background: var(--brand); color: #fff; display: grid; place-items: center; font-size: 14px;
}
.ex-cover h1 { font-size: 28px; line-height: 34px; margin: 16px 0 4px; }
.ex-sub { color: var(--ink2); font-size: 13px; }
.ex-glance { width: 100%; border-collapse: collapse; margin-top: 18px; font-size: 11.5px; }
.ex-glance th {
  text-align: left; font-size: 9.5px; text-transform: uppercase; letter-spacing: .06em; color: var(--ink2); font-weight: 700;
  padding: 0 10px 6px 0; border-bottom: 1.5px solid var(--ink);
}
.ex-glance td { padding: 7px 10px 7px 0; border-bottom: 1px solid #ececf0; vertical-align: top; }
.ex-glance td:first-child { white-space: nowrap; font-weight: 700; }
.ex-glance td:nth-child(2), .ex-glance td:nth-child(4) { white-space: nowrap; font-variant-numeric: tabular-nums; }
.ex-glance td:last-child { white-space: nowrap; }
.ex-glance tr.empty td { color: var(--ink3); font-weight: 400; }
.ex-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; vertical-align: 1px; background: var(--ok); }
.ex-dot.warn { background: var(--warn); }
.ex-dot.bad { background: var(--bad); }
.ex-dots { display: flex; gap: 14px; font-size: 10px; color: var(--ink2); margin-top: 6px; }
.ex-notes { margin-top: 18px; background: var(--canvas); border-radius: 12px; padding: 12px 16px; }
.ex-notes h3 { font-size: 12.5px; }
.ex-notes ul { margin: 4px 0 0; padding-left: 16px; }
.ex-notes li { font-size: 10.5px; line-height: 15px; color: var(--ink2); margin-top: 3px; }
.ex-empty { margin: 28px 0; color: var(--ink2); }
.ex-after { break-inside: avoid; margin-top: 22px; }

.ex-day { margin-top: 26px; padding-top: 16px; border-top: 2px solid var(--ink); }
.ex-day-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; }
.ex-eyebrow { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: var(--brand); font-weight: 700; }
.ex-day-head h2 { font-size: 24px; line-height: 30px; font-variant-numeric: tabular-nums; }
.ex-facts { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; justify-content: flex-end; font-size: 11.5px; color: var(--ink2); }
.ex-verdict { margin: 10px 0; padding: 7px 12px; border-radius: 10px; font-size: 11.5px; font-weight: 600; background: var(--ok-bg); color: #1c6b31; }
.ex-verdict.warn { background: var(--warn-bg); color: #7a4a00; }
.ex-verdict.bad { background: var(--bad-bg); color: var(--bad); }
.ex-map { display: block; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); line-height: 0; }
.ex-map svg { width: 100%; height: auto; display: block; background: #f2efe9; }
.ex-map path { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.ex-map path.casing { stroke: #fff; stroke-width: 8; opacity: .95; }
.ex-map path.walk { stroke: var(--brand); stroke-width: 4.5; }
.ex-map path.walk.back { stroke-dasharray: 7 7; }
.ex-map .stop circle { stroke-width: 2.5; }
.ex-map .stop text { font: 800 12px Inter, sans-serif; text-anchor: middle; fill: var(--ink); }
.ex-map circle.start { fill: #fff; stroke: #0f172a; stroke-width: 3; }
.ex-map circle.end { fill: #0f172a; stroke: #fff; stroke-width: 2; }
.ex-map text.end-label, .ex-map text.attrib { paint-order: stroke; stroke: #fff; stroke-linejoin: round; }
.ex-map text.end-label { font: 700 11px Inter, sans-serif; text-anchor: middle; fill: #0f172a; stroke-width: 3px; }
.ex-map text.attrib { font: 9px Inter, sans-serif; text-anchor: end; fill: #555; stroke-width: 2.5px; }
.ex-map-note { font-size: 9.5px; line-height: 13px; color: var(--ink3); margin: 5px 0 6px; }
.ex-stops { width: 100%; border-collapse: collapse; font-size: 12px; }
.ex-stops td { padding: 5px 10px 5px 0; vertical-align: top; }
.ex-stops td small { display: block; font-size: 10px; line-height: 14px; color: var(--ink2); }
.ex-stops td small.note { color: var(--bad); }
.ex-stops td.t { width: 54px; font-variant-numeric: tabular-nums; }
.ex-stops td:nth-child(2) { width: 34px; padding-right: 8px; }
.ex-stops td:nth-child(2) i {
  display: grid; place-items: center; width: 24px; height: 24px; margin: 0 auto; border-radius: 50%; font: 800 11.5px Inter, sans-serif;
  font-style: normal; color: var(--ink);
}
.ex-stops td:nth-child(2) i.lv0 { background: #e5e7eb; }      /* street busyness on arrival, as on the day map */
.ex-stops td:nth-child(2) i.lv1 { background: var(--quiet); }
.ex-stops td:nth-child(2) i.lv2 { background: var(--moderate); }
.ex-stops td:nth-child(2) i.lv3 { background: var(--busy); color: #fff; }
.ex-stops td.r { text-align: right; width: 96px; white-space: nowrap; padding-right: 0; }
.ex-stops .ex-place { font-size: 13px; font-weight: 700; color: var(--ink); }
.ex-stops a.ex-place { text-decoration: underline; text-decoration-color: rgba(0, 113, 227, .4); text-underline-offset: 2px; }
.ex-stops tr.bad .ex-place { color: var(--bad); }
.ex-stops tr.ex-start td:nth-child(2) i { width: 14px; height: 14px; border: 3px solid #0f172a; background: #fff; }
.ex-stops tr.ex-rest td:nth-child(2) i { background: #fff8d6; box-shadow: 0 0 0 1px #f3d36b; font-size: 11px; }
.ex-stops tr.ex-back td:nth-child(2) i { color: #fff; background: var(--ok); }
.ex-stops tr.ex-back td:nth-child(2) i.late { background: var(--bad); }
.ex-stops tr.ex-walk td { padding: 0 10px 0 0; font-size: 10.5px; color: var(--ink2); vertical-align: middle; }
.ex-stops tr.ex-walk td:nth-child(2) i { width: 0; height: 22px; border-left: 2px dotted var(--ink3); border-radius: 0; }
.ex-stops tr.ex-part td {
  padding: 10px 0 4px; font: 800 10.5px Nunito, Inter, sans-serif; text-transform: uppercase; letter-spacing: .07em;
  color: var(--ink2); border-bottom: 1px solid var(--line);
}
.ex-stops tr.ex-part span { text-transform: none; letter-spacing: 0; font: 600 11px Inter, sans-serif; color: var(--brand-dark); margin-left: 8px; }
.ex-foot { margin-top: 26px; padding-top: 10px; border-top: 1px solid var(--line); font-size: 9.5px; line-height: 13px; color: var(--ink3); }

/* printing (Save as PDF) while the export is open: only the document, one A4 page after another */
@media print {
  @page {
    size: A4; margin: 12mm 14mm 14mm;
    @bottom-right { content: counter(page) " / " counter(pages); font: 9px Inter, sans-serif; color: #8e8e93; }
  }
  body.export-open { height: auto; background: #fff; }
  body.export-open .app, body.export-open .sheet, body.export-open .sheet-backdrop,
  body.export-open .export-bar, body.export-open #shiny-notification-panel { display: none !important; }
  body.export-open .export-view { position: static; display: block; background: none; }
  body.export-open .export-scroll { overflow: visible; padding: 0; }
  body.export-open .ex-paper { width: auto; margin: 0; padding: 0; box-shadow: none; border-radius: 0; }
  body.export-open .ex-trip .ex-day { break-before: page; margin-top: 0; }   /* whole trip: each free time on a page of its own */
  body.export-open .ex-cover h1 { margin-top: 10px; }
  /* a long free time may run onto the next page, but never inside the map or a stop */
  body.export-open .ex-map, body.export-open .ex-stops tr { break-inside: avoid; }
  body.export-open .ex-day-head, body.export-open .ex-verdict { break-after: avoid; }
  body.export-open .ex-paper * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  /* Bootstrap's own print rules make everything black on white and print each link's address after
     it; the document keeps its colours and its links stay links */
  body.export-open .ex-paper a[href]::after { content: none !important; }
  .ex-paper a, .ex-stops tr.ex-part span { color: var(--brand-dark) !important; }
  .ex-paper .ex-place { color: var(--ink) !important; }
  .ex-stops tr.bad .ex-place, .ex-stops td small.note { color: var(--bad) !important; }
  .ex-eyebrow { color: var(--brand) !important; }
  .ex-sub, .ex-facts, .ex-stops td small, .ex-map-note, .ex-notes li, .ex-glance th, .ex-dots, .ex-stops tr.ex-walk td,
  .ex-stops tr.ex-part td, .ex-paper .effort small { color: var(--ink2) !important; }
  .ex-glance tr.empty td, .ex-foot { color: var(--ink3) !important; }
  .ex-brand span { background: var(--brand) !important; color: #fff !important; }
  .ex-notes { background: var(--canvas) !important; }
  .ex-verdict { background: var(--ok-bg) !important; color: #1c6b31 !important; }
  .ex-verdict.warn { background: var(--warn-bg) !important; color: #7a4a00 !important; }
  .ex-verdict.bad { background: var(--bad-bg) !important; color: var(--bad) !important; }
  .ex-dot { background: var(--ok) !important; }
  .ex-dot.warn { background: var(--warn) !important; }
  .ex-dot.bad { background: var(--bad) !important; }
  .ex-stops td:nth-child(2) i.lv0 { background: #e5e7eb !important; }
  .ex-stops td:nth-child(2) i.lv1 { background: var(--quiet) !important; }
  .ex-stops td:nth-child(2) i.lv2 { background: var(--moderate) !important; }
  .ex-stops td:nth-child(2) i.lv3 { background: var(--busy) !important; color: #fff !important; }
  .ex-stops tr.ex-start td:nth-child(2) i { background: #fff !important; }
  .ex-stops tr.ex-rest td:nth-child(2) i { background: #fff8d6 !important; }
  .ex-stops tr.ex-back td:nth-child(2) i { background: var(--ok) !important; color: #fff !important; }
  .ex-stops tr.ex-back td:nth-child(2) i.late { background: var(--bad) !important; }
  .ex-paper .effort i b { background: var(--line) !important; }
  .ex-paper .effort.e1 i b:nth-child(1), .ex-paper .effort.e2 i b:nth-child(-n+2), .ex-paper .effort.e3 i b { background: var(--ink) !important; }
}
.ex-stops td small.wait { color: var(--ink2); font-style: italic; }

/* ---- the Overview menu in the top bar (nav_menu in R/eat_stay.R, www/app.js toggleNavMenu) ----
   The button says which overview page is open; the round blue chevron says it opens a menu. */
.nav-menu { position: relative; flex: none; }
.trip-tabs .nav-overview { gap: 10px; padding: 0 8px 0 12px; border: 1px solid var(--line); background: #fff; }
.trip-tabs .nav-overview:hover { border-color: var(--brand); background: #fff; }
.trip-tabs .nav-overview.active { border-color: #b9d6f6; background: var(--brand-soft); }
.nav-overview .nav-label { display: flex; flex-direction: column; align-items: flex-start; line-height: 1.2; }
.trip-tabs .nav-overview .nav-label small { font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--ink2); }
.nav-overview .nav-label strong { font-size: 14px; color: var(--ink); }
.nav-overview.active .nav-label strong { color: var(--brand-dark); }
.nav-caret {
  width: 24px; height: 24px; border-radius: 50%; background: var(--brand); color: #fff;
  display: grid; place-items: center; transition: transform .2s ease;
}
.trip-tabs .nav-overview .nav-caret svg { width: 14px; height: 14px; stroke-width: 2.6; }
body.nav-open .nav-caret { transform: rotate(180deg); }
.nav-dropdown {
  display: none; position: absolute; top: calc(100% + 8px); left: 0; width: 310px; padding: 6px;
  background: #fff; border: 1px solid var(--line); border-radius: var(--r-card); box-shadow: var(--floating); z-index: 200;
}
body.nav-open .nav-dropdown { display: block; }
.trip-tabs .nav-dropdown button { width: 100%; height: auto; padding: 10px; gap: 12px; color: var(--ink); justify-content: flex-start; }
.trip-tabs .nav-dropdown button:hover { background: var(--canvas); }
.trip-tabs .nav-dropdown button.current { background: var(--brand-soft); }
.nav-item-icon { width: 36px; height: 36px; border-radius: 10px; background: var(--canvas); color: var(--brand-dark); display: grid; place-items: center; flex: none; }
.nav-dropdown button.current .nav-item-icon { background: var(--brand); color: #fff; }
.nav-item-icon svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.nav-item-text { display: flex; flex-direction: column; align-items: flex-start; gap: 1px; text-align: left; white-space: normal; }
.trip-tabs .nav-dropdown .nav-item-text small { font-size: 12px; font-weight: 500; color: var(--ink2); }

/* ---- Where to eat / Where to stay (R/eat_stay.R): list on the left, map on the right ---- */
.es-page { display: flex; flex-direction: column; gap: 20px; }
.es-filters { display: flex; align-items: center; gap: 10px 18px; flex-wrap: wrap; }
.es-filters .form-group, .es-filters .checkbox { margin: 0; }
.es-filters .shiny-input-container:not(.shiny-input-container-inline) { width: auto !important; }
.es-filters label { font-size: 13px; font-weight: 500; }
.es-filters .checkbox-inline { margin: 0 6px 0 0; padding: 6px 12px 6px 30px; border: 1px solid var(--line); border-radius: var(--r-pill); background: #fff; }
.es-filters .checkbox label { padding: 6px 12px 6px 30px; border: 1px solid var(--line); border-radius: var(--r-pill); background: #fff; }
.es-filters .checkbox input[type=checkbox], .es-filters .checkbox-inline input[type=checkbox] { margin-left: -20px; }
.es-filters .selectize-control { width: 260px; }
.es-map .leaflet-tile-pane { filter: grayscale(.8) brightness(1.06) contrast(.85); }   /* as on the day map */
.es-cols { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 20px; align-items: start; }
.es-list > div { display: flex; flex-direction: column; gap: 16px; }
.es-list { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.es-list .night { grid-template-columns: 170px minmax(0, 1fr); }
.es-list .night-addr { width: 230px; }
.es-map {
  position: sticky; top: 16px; height: calc(100vh - 76px - 64px); min-height: 460px; border-radius: var(--r-sheet);
  overflow: hidden; border: 1px solid var(--line); box-shadow: var(--shadow); background: #e8e8ed;
}
.es-day { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-sheet); padding: 18px; box-shadow: var(--shadow); }
.es-day > h3 { margin-bottom: 10px; }
.es-meal { border: 1px solid var(--line); border-radius: var(--r-card); padding: 12px 14px; cursor: pointer; }
.es-meal + .es-meal { margin-top: 10px; }
.es-meal:hover { border-color: #b9d6f6; }
.es-meal.focus { border-color: var(--brand); box-shadow: 0 0 0 1px var(--brand); }
.es-meal-head { display: flex; flex-direction: column; gap: 2px; margin-bottom: 6px; }
.es-meal-head strong { font-size: 15px; }
.es-meal-head span { color: var(--ink2); font-size: 13px; }
.es-row { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 0 12px; padding: 8px 0; border-top: 1px solid var(--line); align-items: baseline; }
.es-row a, .es-stay a { font-weight: 600; color: var(--ink); text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.es-row a:hover, .es-stay a:hover { color: var(--brand-dark); text-decoration: underline; }
.es-row small { grid-column: 1 / -1; color: var(--ink2); font-size: 12px; }
.es-kind { font-size: 12px; color: var(--ink2); }
.es-walk { font-size: 12px; font-weight: 600; color: var(--brand-dark); }
.es-none { color: var(--ink2); font-size: 13px; }
.es-empty { background: var(--surface); border: 1px dashed var(--line); border-radius: var(--r-card); padding: 24px; color: var(--ink2); }
.es-summary { background: var(--brand-soft); color: var(--brand-dark); border-radius: var(--r-card); padding: 12px 16px; display: flex; flex-direction: column; gap: 2px; font-size: 13px; }
.es-stay {
  display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 12px; align-items: center; cursor: pointer;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-card); padding: 12px 14px;
}
.es-stay:hover { border-color: var(--brand); }
.es-stay a { display: block; }
.es-stay small { display: block; color: var(--ink2); font-size: 12px; }
.es-rank { width: 28px; height: 28px; border-radius: 50%; background: #334155; color: #fff; display: grid; place-items: center; font-size: 13px; }
.es-stay-walk { text-align: right; white-space: nowrap; }
.es-stay-walk strong { font-size: 16px; }
.es-stay .es-far { margin-top: 2px; color: var(--ink); }
.leaflet-tooltip.stay-rank-label { color: #fff; font-weight: 800; font-size: 11px; }

/* ---- day cards that fold (www/app.js toggleFold) and "+ Add a day" ---- */
.fold-btn {
  width: 26px; height: 26px; flex: none; border: 1px solid var(--line); border-radius: 50%; background: #fff;
  color: var(--ink2); display: grid; place-items: center; cursor: pointer; padding: 0; transition: transform .2s ease;
}
.fold-btn:hover { border-color: var(--brand); color: var(--brand-dark); }
.fold-btn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.folded .fold-btn { transform: rotate(-90deg); }
.fold-sum { display: none; }
.folded .fold-sum { display: inline; color: var(--ink2); }
.day-row.folded .day-track { display: none; }
.day-row.folded .day-label > small:not(.fold-sum), .day-row.folded .day-label .effort { display: none; }
.day-row .day-label .fold-sum { max-width: 46ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.es-day.folded .fold-body { display: none; }
.fold-head { display: flex; align-items: center; gap: 10px; cursor: pointer; }
.fold-head h3 { margin: 0; }
.fold-head .fold-sum { font-size: 13px; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fold-head .fold-btn { margin-left: auto; }
.es-day .fold-head { margin-bottom: 10px; }
.es-day.folded .fold-head { margin-bottom: 0; }
.fold-all { display: flex; gap: 4px; margin-left: auto; }
.days > .fold-all { justify-content: flex-end; margin: 0 0 4px; }
.fold-all button { border: 0; background: none; color: var(--brand-dark); font-size: 12px; font-weight: 600; cursor: pointer; padding: 4px 6px; border-radius: 8px; }
.fold-all button:hover { background: var(--brand-soft); }
.add-day {
  width: 100%; margin: 10px 0 4px; min-height: 52px; border: 1.5px dashed #c7c7cc; border-radius: var(--r-card);
  background: transparent; color: var(--ink2); font-weight: 600; display: flex; align-items: center; justify-content: center;
  gap: 10px; cursor: pointer;
}
.add-day:hover { border-color: var(--brand); color: var(--brand-dark); background: var(--brand-soft); }
.add-day-plus { width: 26px; height: 26px; border-radius: 50%; background: var(--brand); color: #fff; display: grid; place-items: center; font-size: 18px; line-height: 1; }

/* ---- Where to eat: when you eat ---- */
.es-meal-title { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.es-time { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--ink2); }
.es-time select { border: 1px solid var(--line); border-radius: 8px; padding: 2px 6px; font: inherit; color: var(--ink); background: #fff; }
.es-len { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ink2); }
.es-len .shiny-input-container { width: 110px !important; }

/* ---- Where to stay: your nights ---- */
.nights { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-sheet); padding: 18px; box-shadow: var(--shadow); }
.nights-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 10px; }
.nights-head span { color: var(--ink2); font-size: 13px; }
.night {
  display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 6px 16px; align-items: center;
  padding: 10px 12px; border: 1px solid var(--line); border-radius: var(--r-card); cursor: pointer;
}
.night + .night { margin-top: 8px; }
.night:hover { border-color: #b9d6f6; }
.night.active { border-color: var(--brand); box-shadow: 0 0 0 1px var(--brand); background: #fafcff; }
.night.off { cursor: default; background: var(--canvas); }
.night-date { display: flex; flex-direction: column; gap: 2px; }
.night-opt { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 500; color: var(--ink2); margin: 0; }
.night-choice { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.night-choice small { color: var(--ink2); font-size: 12px; }
.night-choice .night-walks { color: var(--brand-dark); }
.muted { color: var(--ink2); }
.night-actions { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding-top: 6px; border-top: 1px dashed var(--line); font-size: 13px; }
.night-actions .btn { min-height: 32px; font-size: 13px; padding: 0 12px; }
.night-actions .btn.on, .nights-every .btn.on { border-color: var(--brand); color: var(--brand-dark); background: var(--brand-soft); }
.addr-box { display: flex; gap: 6px; }
.night-addr { width: 280px; border: 1px solid var(--line); border-radius: var(--r-input); padding: 6px 10px; font: inherit; }
.nights-every { display: flex; align-items: center; gap: 10px; margin-top: 10px; font-size: 13px; }
.nights-every .btn { min-height: 32px; font-size: 13px; padding: 0 12px; }
.es-pick { margin-top: 6px; min-height: 30px; font-size: 12px; padding: 0 12px; }
.es-used { display: inline-block; margin-top: 3px; font-size: 11px; font-weight: 600; color: var(--brand-dark); background: var(--brand-soft); border-radius: var(--r-pill); padding: 1px 8px; }
#stay_map.pin-mode, #stay_map.pin-mode .leaflet-interactive { cursor: crosshair; }

/* ---- one free time: its hours at the top of the plan card (hour + minute lists that read as the title) ---- */
.plan-times { display: flex; align-items: center; gap: 4px; margin-top: 1px; }
.plan-times > span { font: 800 18px/24px Nunito, Inter, sans-serif; }

/* ---- Trip settings: how often you exercise (R/effort.R FITNESS) ---- */
.fitness-card .shiny-options-group { display: flex; gap: 6px; flex-wrap: wrap; }
.fitness-card .radio-inline { margin: 0; padding: 0; }
.fitness-card .radio-inline input { position: absolute; opacity: 0; pointer-events: none; }
.fitness-card .radio-inline > span {
  display: inline-block; padding: 8px 16px; border: 1px solid var(--line); border-radius: var(--r-pill); background: #fff;
  font-weight: 600; cursor: pointer;
}
.fitness-card .radio-inline input:checked + span { background: var(--brand); border-color: var(--brand); color: #fff; }
.fitness-card .radio-inline input:focus-visible + span { outline: 2px solid var(--blue); outline-offset: 2px; }

/* ---- Where to stay: the one search box ---- */
.stay-search { position: relative; flex: 1 1 280px; min-width: 240px; }
.stay-search input {
  width: 100%; border: 1px solid var(--line); border-radius: var(--r-input); padding: 8px 12px; font: inherit; background: #fff;
}
.stay-search input:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft); }
.stay-suggest { position: absolute; left: 0; right: 0; top: calc(100% + 4px); z-index: 30; background: #fff; border-radius: 12px; box-shadow: var(--floating); overflow: hidden; }
.stay-suggest:empty { display: none; }
.stay-suggest .sug { display: flex; gap: 10px; align-items: center; width: 100%; border: 0; background: none; padding: 8px 12px; text-align: left; cursor: pointer; }
.stay-suggest .sug + .sug { border-top: 1px solid var(--line); }
.stay-suggest .sug:hover { background: var(--brand-soft); }
.stay-suggest .sug i { font-style: normal; }
.stay-suggest .sug span { display: flex; flex-direction: column; min-width: 0; }
.stay-suggest .sug b { font-weight: 600; }
.stay-suggest .sug small { color: var(--ink2); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.stay-suggest .sug-none { padding: 10px 12px; color: var(--ink2); font-size: 13px; }

/* ---- Where to eat: worth a trip for the food, and booked meals ---- */
.must-eat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-sheet); padding: 18px; box-shadow: var(--shadow); }
.must-head { display: flex; flex-direction: column; gap: 10px; margin-bottom: 10px; }
.must-head p { color: var(--ink2); font-size: 13px; margin-top: 2px; }
.must-q { width: 100%; border: 1px solid var(--line); border-radius: var(--r-input); padding: 8px 12px; font: inherit; }
.must-q:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft); }
.must-list { max-height: 420px; overflow: auto; display: flex; flex-direction: column; gap: 8px; padding-right: 4px; }
.must-item { display: flex; gap: 12px; align-items: center; justify-content: space-between; border: 1px solid var(--line); border-radius: var(--r-card); padding: 10px 12px; cursor: pointer; }
.must-item:hover { border-color: #b9d6f6; }
.must-item.booked { border-color: var(--brand); background: #fafcff; }
.must-main { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.must-main small { color: var(--ink2); font-size: 12px; }
.must-why { font-size: 13px; }
.must-main .must-dish { color: var(--ink); }
.must-actions { display: flex; flex-direction: column; gap: 6px; flex: none; }
.must-actions .btn { min-height: 30px; font-size: 12px; padding: 0 12px; justify-content: center; }
.es-booked { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 10px; align-items: center; border: 1px solid var(--brand); background: var(--brand-soft); border-radius: var(--r-card); padding: 10px 12px; margin-bottom: 10px; }
.es-booked small { display: block; color: var(--brand-dark); font-size: 12px; }
.es-booked .btn { min-height: 30px; font-size: 12px; padding: 0 12px; }
.book-options { display: flex; flex-direction: column; gap: 8px; }
.book-options .btn { justify-content: flex-start; }
.book-warn { color: #8a5300; background: var(--warn-bg); border-radius: 10px; padding: 8px 10px; font-size: 13px; }

/* ---- day page: hours as hour + minute lists; start or end somewhere else ---- */
.plan-times-inputs { display: none; }
.hm { display: inline-flex; align-items: baseline; gap: 1px; }
.hm b { font: 800 18px/24px Nunito, Inter, sans-serif; }
.hm select {
  font: 800 18px/24px Nunito, Inter, "PingFang SC", sans-serif; color: var(--ink); border: 0; border-bottom: 2px dashed #b9d6f6;
  background: transparent; padding: 0 2px; cursor: pointer; appearance: none; -webkit-appearance: none; text-align: center;
}
.hm select:hover, .hm select:focus { border-bottom-color: var(--brand); outline: none; background: var(--brand-soft); border-radius: 4px 4px 0 0; }
.own-point { grid-column: 1 / -1; }
.link-btn { border: 0; background: none; padding: 0; color: var(--brand-dark); font-size: 12px; font-weight: 600; cursor: pointer; }
.link-btn:hover { text-decoration: underline; }
.own-point-body { display: none; margin-top: 8px; gap: 8px; flex-direction: column; }
.own-point.open .own-point-body { display: flex; }
.own-point-which { display: inline-flex; gap: 4px; padding: 3px; background: #e8e8ed; border-radius: var(--r-pill); align-self: flex-start; }
.own-point-which button { border: 0; background: none; border-radius: var(--r-pill); padding: 4px 12px; font-size: 12px; font-weight: 600; color: var(--ink2); cursor: pointer; }
.own-point-which button.on { background: #fff; color: var(--ink); box-shadow: 0 1px 3px rgba(0, 0, 0, .12); }
.own-point .stay-search { min-width: 0; }
.map-pick { margin-top: 8px; min-height: 30px; font-size: 12px; padding: 0 12px; }
.nights-every { flex-wrap: wrap; }
.nights-every .stay-search { flex-basis: 100%; }

/* ---- Where to eat: places around the middle of the walks; saved restaurants ---- */
.es-walkgroup + .es-walkgroup { margin-top: 8px; }
.es-walkhead { display: block; color: var(--brand-dark); font-weight: 600; font-size: 12px; margin: 4px 0 2px; }
.must-item.saved { border-color: var(--brand); background: #fafcff; }
.food-more { margin-top: 12px; }
.food-more h4 { font-size: 13px; margin: 0 0 8px; color: var(--ink2); }
.must-eat { margin-top: 4px; }

